package main

import (
	"math"
	"strconv"
	"strings"
)

// Value types
const (
	VNull = iota
	VInt
	VReal
	VText
	VBlob
)

// Value is a SQL value.
type Value struct {
	T int
	I int64
	F float64
	S string
}

func NullValue() Value      { return Value{T: VNull} }
func IntValue(i int64) Value { return Value{T: VInt, I: i} }
func RealValue(f float64) Value { return Value{T: VReal, F: f} }
func TextValue(s string) Value { return Value{T: VText, S: s} }
func BlobValue(s string) Value { return Value{T: VBlob, S: s} }

// IsNum reports whether the value is numeric (int or real).
func (v Value) IsNum() bool { return v.T == VInt || v.T == VReal }

// ToNum converts the value to a numeric value (int if possible).
func (v Value) ToNum() Value {
	switch v.T {
	case VInt:
		return v
	case VReal:
		return v
	case VNull:
		return NullValue()
	default:
		s := strings.TrimSpace(v.S)
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return IntValue(i)
		}
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			// if it is an exact integer, store as int
			if f == math.Trunc(f) && math.Abs(f) < 1e15 {
				return RealValue(f)
			}
			return RealValue(f)
		}
		return IntValue(0)
	}
}

// ToReal converts to a float64.
func (v Value) ToReal() float64 {
	switch v.T {
	case VInt:
		return float64(v.I)
	case VReal:
		return v.F
	case VNull:
		return 0
	default:
		f, _ := strconv.ParseFloat(strings.TrimSpace(v.S), 64)
		return f
	}
}

// ToInt converts to an int64.
func (v Value) ToInt() int64 {
	switch v.T {
	case VInt:
		return v.I
	case VReal:
		return int64(v.F)
	case VNull:
		return 0
	default:
		s := strings.TrimSpace(v.S)
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i
		}
		f, _ := strconv.ParseFloat(s, 64)
		return int64(f)
	}
}

// ToText converts the value to its text representation.
func (v Value) ToText() string {
	switch v.T {
	case VInt:
		return strconv.FormatInt(v.I, 10)
	case VReal:
		return fmtFloat(v.F)
	case VNull:
		return ""
	default:
		return v.S
	}
}

// FormatReal formats a float like SQLite/Go %v.
func fmtFloat(f float64) string {
	return strconv.FormatFloat(f, 'g', -1, 64)
}

// TypeName returns the type name like SQLite typeof().
func (v Value) TypeName() string {
	switch v.T {
	case VNull:
		return "null"
	case VInt:
		return "integer"
	case VReal:
		return "real"
	case VBlob:
		return "blob"
	default:
		return "text"
	}
}

// Compare compares two values with SQLite semantics (no affinity handling).
// Returns -1, 0, 1. Both must be non-null.
func (a Value) CmpRaw(b Value) int {
	// type ordering: null < int/real < text < blob
	ta := typeRank(a)
	tb := typeRank(b)
	if ta != tb {
		if ta < tb {
			return -1
		}
		return 1
	}
	switch ta {
	case 1: // numeric
		if a.T == VInt && b.T == VInt {
			if a.I < b.I {
				return -1
			} else if a.I > b.I {
				return 1
			}
			return 0
		}
		// compare int with real
		if a.T == VInt {
			return cmpFloat(float64(a.I), b.F)
		}
		if b.T == VInt {
			return cmpFloat(a.F, float64(b.I))
		}
		return cmpFloat(a.F, b.F)
	case 3: // blob
		return strings.Compare(a.S, b.S)
	default: // text
		return strings.Compare(a.S, b.S)
	}
}

func typeRank(v Value) int {
	switch v.T {
	case VNull:
		return 0
	case VInt, VReal:
		return 1
	case VBlob:
		return 3
	default:
		return 2
	}
}

func cmpFloat(a, b float64) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

// Equal compares for equality.
func (a Value) Equal(b Value) bool { return a.CmpRaw(b) == 0 }
EOF
echo ok"}

