package main

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Token types
const (
	TokEOF = iota
	TokIdent     // identifier or quoted identifier
	TokNum       // numeric literal
	TokStr       // string literal
	TokBlob      // x'..' blob literal
	TokPunct     // punctuation/operator
	TokSpace     // whitespace (only kept in the raw token list for debug)
	TokParam     // ? or : or @ or $
)

// Token is a lexical token.
type Token struct {
	Type int
	Text string // original text (for idents: the unquoted name)
	Raw  string // raw text as written
}

// Lexer tokenizes SQL text.
type Lexer struct {
	src  string
	pos  int
	toks []Token
}

func tokenize(sql string) ([]Token, error) {
	l := &Lexer{src: sql}
	var toks []Token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		if t.Type == TokEOF {
			break
		}
		toks = append(toks, t)
	}
	return toks, nil
}

func isIdentStart(c rune) bool {
	return unicode.IsLetter(c) || c == '_' || c > 127
