		if l.pos < len(l.src) && unicode.IsDigit(runeAt(l.src, l.pos)) {
			for l.pos < len(l.src) && unicode.IsDigit(runeAt(l.src, l.pos)) {
				l.pos++
			}
		} else {
			l.pos = save
		}
	}
}

func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func runeAt(s string, i int) rune {
	r, _ := utf8.DecodeRuneInString(s[i:])
	return r
}
EOF
echo ok"}

