cd /workspace/trdsql && cat > parser.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Parser parses a single SQL statement (SELECT).
type Parser struct {
	toks []Token
	pos  int
}

func NewParser(toks []Token) *Parser { return &Parser{toks: toks} }

func (p *Parser) cur() Token {
	if p.pos < len(p.toks) {
		return p.toks[p.pos]
	}
	return Token{Type: TokEOF}
}

func (p *Parser) next() Token {
	t := p.cur()
	p.pos++
	return t
}

func (p *Parser) isKw(kw string) bool {
	t := p.cur()
	return t.Type == TokIdent && strings.EqualFold(t.Text, kw)
}

func (p *Parser) isPunct(s string) bool {
	t := p.cur()
	return t.Type == TokPunct && t.Text == s
}

func (p *Parser) acceptKw(kw string) bool {
	if p.isKw(kw) {
		p.next()
		return true
	}
	return false
}

func (p *Parser) acceptPunct(s string) bool {
	if p.isPunct(s) {
		p.next()
		return true
	}
	return false
}

func (p *Parser) expectPunct(s string) error {
	if p.acceptPunct(s) {
		return nil
	}
	t := p.cur()
	if t.Type == TokEOF {
		return fmt.Errorf("incomplete input")
	}
	return fmt.Errorf("near %q: syntax error", t.Raw)
}

func (p *Parser) skipSpace() {
	for p.cur().Type == TokSpace {
		p.pos++
	}
}

func (p *Parser) peekNonSpace() Token {
	i := p.pos
	for i < len(p.toks) && p.toks[i].Type == TokSpace {
		i++
	}
	if i < len(p.toks) {
		return p.toks[i]
	}
	return Token{Type: TokEOF}
}

func isReserved(kw string) bool {
	switch strings.ToLower(kw) {
	case "select", "from", "where", "group", "by", "having", "order", "limit", "offset",
		"union", "intersect", "except", "join", "left", "right", "full", "inner", "outer",
		"cross", "natural", "on", "using", "as", "and", "or", "not", "in", "is", "null",
		"like", "glob", "regexp", "match", "escape", "between", "case", "when", "then",
		"else", "end", "distinct", "all", "asc", "desc", "collate", "with", "values",
		"true", "false", "current", "nulls", "first", "last", "cast", "collatenow":
		return true
	}
	return false
}

// Parse parses one statement.
func (p *Parser) Parse() (*Select, error) {
	p.skipSpace()
	sel, err := p.parseSelect()
	if err != nil {
		return nil, err
	}
	p.skipSpace()
	if p.cur().Type != TokEOF {
		t := p.cur()
		return nil, fmt.Errorf("near %q: syntax error", t.Raw)
	}
	return sel, nil
}

func (p *Parser) parseSelect() (*Select, error) {
	var with []CTE
	if p.acceptKw("WITH") {
		if p.acceptKw("RECURSIVE") {
		}
		for {
			// parse CTE name
			if p.cur().Type != TokIdent {
				return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
			}
			name := p.next().Text
			var cols []string
			if p.acceptPunct("(") {
				for {
					if p.cur().Type != TokIdent {
						return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
					}
					cols = append(cols, p.next().Text)
					if p.acceptPunct(",") {
						continue
					}
					break
				}
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
			}
			if !p.acceptKw("AS") {
				return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
			}
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			sub, err := p.parseSelect()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			with = append(with, CTE{Name: name, Cols: cols, Sel: sub})
			if p.acceptPunct(",") {
				continue
			}
			break
		}
	}
	sel, err := p.parseTerm(with)
	if err != nil {
		return nil, err
	}
	// compound
	for {
		op := ""
		if p.acceptKw("UNION") {
			op = "UNION"
			if p.acceptKw("ALL") {
				op = "UNION ALL"
			}
		} else if p.acceptKw("INTERSECT") {
			op = "INTERSECT"
		} else if p.acceptKw("EXCEPT") {
			op = "EXCEPT"
		}
		if op == "" {
			break
		}
		p.skipSpace()
		rhs, err := p.parseTerm(with)
		if err != nil {
			return nil, err
		}
		// fold left
		if sel.Compound != nil && sel.Order != nil {
			// orders apply to the whole compound in SQLite
		}
		rhs.CompoundOp = op
		rhs.With = with
		if sel.Compound == nil {
			sel.Compound = rhs
		} else {
			// append to the end of the compound chain
			tail := sel
			for tail.Compound != nil {
				tail = tail.Compound
			}
			tail.Compound = rhs
		}
	}
	return sel, nil
}

func (p *Parser) parseTerm(with []CTE) (*Select, error) {
	sel := &Select{With: with}
	if !p.acceptKw("SELECT") {
		return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
	}
	if p.acceptKw("DISTINCT") {
		sel.Distinct = true
	} else if p.acceptKw("ALL") {
		sel.All = true
	}
	for {
		col, err := p.parseSelectCol()
		if err != nil {
			return nil, err
		}
		sel.Cols = append(sel.Cols, col)
		if p.acceptPunct(",") {
			p.skipSpace()
			continue
		}
		break
	}
	if p.acceptKw("FROM") {
		p.skipSpace()
		if err := p.parseFrom(sel); err != nil {
			return nil, err
		}
	}
	if p.acceptKw("WHERE") {
		p.skipSpace()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		sel.Where = e
	}
	if p.acceptKw("GROUP") {
		if !p.acceptKw("BY") {
			return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
		}
		p.skipSpace()
		for {
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			sel.Group = append(sel.Group, e)
			if p.acceptPunct(",") {
				p.skipSpace()
				continue
			}
			break
		}
	}
	if p.acceptKw("HAVING") {
		p.skipSpace()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		sel.Having = e
	}
	if p.acceptKw("ORDER") {
		if !p.acceptKw("BY") {
			return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
		}
		p.skipSpace()
		for {
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			term := OrderTerm{Expr: e}
			if p.acceptKw("DESC") {
				term.Desc = true
			} else {
				p.acceptKw("ASC")
			}
			if p.acceptKw("NULLS") {
				if p.acceptKw("FIRST") {
					term.Nulls = 1
				} else if p.acceptKw("LAST") {
					term.Nulls = 2
				}
			}
			sel.Order = append(sel.Order, term)
			if p.acceptPunct(",") {
				p.skipSpace()
				continue
			}
			break
		}
	}
	if p.acceptKw("LIMIT") {
		p.skipSpace()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		sel.Limit = e
		if p.acceptKw("OFFSET") {
			p.skipSpace()
			e2, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			sel.Offset = e2
		} else if p.acceptPunct(",") {
			p.skipSpace()
			e2, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			sel.Offset = e2
		}
	}
	return sel, nil
}

func (p *Parser) parseSelectCol() (SelectCol, error) {
	t := p.cur()
	if t.Type == TokPunct && t.Text == "*" {
		p.next()
		return SelectCol{Expr: &StarRef{}}, nil
	}
	// table.* handled in parseExpr
	e, err := p.parseExpr()
	if err != nil {
		return SelectCol{}, err
	}
	alias := ""
	p.skipSpace()
	if p.cur().Type == TokIdent {
		nt := p.cur()
		if !isReserved(nt.Text) {
			p.next()
			alias = nt.Text
		} else if strings.EqualFold(nt.Text, "AS") {
			p.next()
			p.skipSpace()
			if p.cur().Type != TokIdent {
				return SelectCol{}, fmt.Errorf("near %q: syntax error", p.cur().Raw)
			}
			alias = p.next().Text
		}
	}
	return SelectCol{Expr: e, Alias: alias}, nil
}

func (p *Parser) parseFrom(sel *Select) error {
	for {
		tr := TableRef{}
		if p.isPunct("(") {
			p.next()
			sub, err := p.parseSelect()
			if err != nil {
				return err
			}
			if err := p.expectPunct(")"); err != nil {
				return err
			}
			tr.IsSub = true
			tr.Sub = sub
		} else if p.cur().Type == TokIdent {
			tr.Name = p.next().Text
		} else {
			return fmt.Errorf("near %q: syntax error", p.cur().Raw)
		}
		p.skipSpace()
		// alias
		if p.cur().Type == TokIdent {
			nt := p.cur()
			if nt.Type == TokIdent && !isReserved(nt.Text) {
				p.next()
				tr.Alias = nt.Text
			} else if strings.EqualFold(nt.Text, "AS") {
				p.next()
				p.skipSpace()
				if p.cur().Type != TokIdent {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				tr.Alias = p.next().Text
			}
		}
		p.skipSpace()
		sel.From = append(sel.From, tr)
		// join handling
		for {
			p.skipSpace()
			jt := ""
			if p.isPunct(",") {
				p.next()
				jt = "CROSS"
			} else if p.acceptKw("CROSS") {
				if !p.acceptKw("JOIN") {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				jt = "CROSS"
			} else if p.acceptKw("JOIN") {
				jt = "INNER"
			} else if p.acceptKw("LEFT") {
				p.acceptKw("OUTER")
				if !p.acceptKw("JOIN") {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				jt = "LEFT"
			} else if p.acceptKw("RIGHT") {
				p.acceptKw("OUTER")
				if !p.acceptKw("JOIN") {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				jt = "RIGHT"
			} else if p.acceptKw("FULL") {
				p.acceptKw("OUTER")
				if !p.acceptKw("JOIN") {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				jt = "FULL"
			} else if p.acceptKw("INNER") {
				if !p.acceptKw("JOIN") {
					return fmt.Errorf("near %q: syntax error", p.cur().Raw)
				}
				jt = "INNER"
			} else {
				break
			}
			p.skipSpace()
			right := TableRef{}
			if p.isPunct("(") {
				p.next()
				sub, err := p.parseSelect()
				if err != nil {
					return err
				}
				if err := p.expectPunct(")"); err != nil {
					return err
				}
				right.IsSub = true
				right.Sub = sub
			} else if p.cur().Type == TokIdent {
				right.Name = p.next().Text
			} else {
				return fmt.Errorf("near %q: syntax error", p.cur().Raw)
			}
			p.skipSpace()
			if p.cur().Type == TokIdent {
				nt := p.cur()
				if !isReserved(nt.Text) {
					p.next()
					right.Alias = nt.Text
				} else if strings.EqualFold(nt.Text, "AS") {
					p.next()
					p.skipSpace()
					if p.cur().Type != TokIdent {
						return fmt.Errorf("near %q: syntax error", p.cur().Raw)
					}
					right.Alias = p.next().Text
				}
			}
			j := &Join{Type: jt, Right: &right}
			p.skipSpace()
			if p.acceptKw("ON") {
				p.skipSpace()
				e, err := p.parseExpr()
				if err != nil {
					return err
				}
				j.On = e
			} else if p.acceptKw("USING") {
				if err := p.expectPunct("("); err != nil {
					return err
				}
				for {
					if p.cur().Type != TokIdent {
						return fmt.Errorf("near %q: syntax error", p.cur().Raw)
					}
					j.Using = append(j.Using, p.next().Text)
					if p.acceptPunct(",") {
						continue
					}
					break
				}
				if err := p.expectPunct(")"); err != nil {
					return err
				}
			}
			last := &sel.From[len(sel.From)-1]
			last.HasJoin = true
			last.Join = j
			continue
		}
		if p.isPunct(",") {
			p.next()
			p.skipSpace()
			continue
		}
		break
	}
	return nil
}

// parseExpr parses an expression with precedence.
func (p *Parser) parseExpr() (Expr, error) {
	return p.parseOr()
}

func (p *Parser) parseOr() (Expr, error) {
	l, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for {
		if p.acceptKw("OR") {
			p.skipSpace()
			r, err := p.parseAnd()
			if err != nil {
				return nil, err
			}
			l = &BinOp{Op: "OR", L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func (p *Parser) parseAnd() (Expr, error) {
	l, err := p.parseNot()
	if err != nil {
		return nil, err
	}
	for {
		if p.acceptKw("AND") {
			p.skipSpace()
			r, err := p.parseNot()
			if err != nil {
				return nil, err
			}
			l = &BinOp{Op: "AND", L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func (p *Parser) parseNot() (Expr, error) {
	if p.acceptKw("NOT") {
		p.skipSpace()
		e, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		return &UnaryOp{Op: "NOT", E: e}, nil
	}
	return p.parseCompare()
}

func (p *Parser) parseCompare() (Expr, error) {
	l, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	for {
		p.skipSpace()
		t := p.cur()
		// IS / IN / BETWEEN / LIKE / GLOB / REGEXP / comparison operators
		if t.Type == TokIdent {
			lt := strings.ToLower(t.Text)
			switch lt {
			case "is":
				p.next()
				p.skipSpace()
				not := false
				if p.acceptKw("NOT") {
					not = true
					p.skipSpace()
				}
				if p.acceptKw("NULL") {
					l = &NullExpr{E: l, Not: not}
					continue
				}
				// IS [NOT] value
				r, err := p.parseAdd()
				if err != nil {
					return nil, err
				}
				l = &IsExpr{E: l, Val: r, Not: not}
				continue
			case "not":
				// NOT IN / NOT BETWEEN / NOT LIKE ...
				p.next()
				p.skipSpace()
				nt := p.cur()
				if nt.Type == TokIdent {
					nl := strings.ToLower(nt.Text)
					switch nl {
					case "in":
						p.next()
						p.skipSpace()
						e, err := p.parseInBody(l, true)
						if err != nil {
							return nil, err
						}
						l = e
						continue
					case "between":
						p.next()
						p.skipSpace()
						e, err := p.parseBetweenBody(l, true)
						if err != nil {
							return nil, err
						}
						l = e
						continue
					case "like":
						p.next()
						p.skipSpace()
						e, err := p.parseLikeBody(l, true, false)
						if err != nil {
							return nil, err
						}
						l = e
						continue
					case "glob":
						p.next()
						p.skipSpace()
						e, err := p.parseLikeBody(l, true, true)
						if err != nil {
							return nil, err
						}
						l = e
						continue
					case "regexp":
						p.next()
						p.skipSpace()
						r, err := p.parseAdd()
						if err != nil {
							return nil, err
						}
						l = &LikeExpr{E: l, Pat: r, Not: true, Regexp: true}
						continue
					}
				}
				return nil, fmt.Errorf("near %q: syntax error", nt.Raw)
			case "in":
				p.next()
				p.skipSpace()
				e, err := p.parseInBody(l, false)
				if err != nil {
					return nil, err
				}
				l = e
				continue
			case "between":
				p.next()
				p.skipSpace()
				e, err := p.parseBetweenBody(l, false)
				if err != nil {
					return nil, err
				}
				l = e
				continue
			case "like":
				p.next()
				p.skipSpace()
				e, err := p.parseLikeBody(l, false, false)
				if err != nil {
					return nil, err
				}
				l = e
				continue
			case "glob":
				p.next()
				p.skipSpace()
				e, err := p.parseLikeBody(l, false, true)
				if err != nil {
					return nil, err
				}
				l = e
				continue
			case "regexp":
				p.next()
				p.skipSpace()
				r, err := p.parseAdd()
				if err != nil {
					return nil, err
				}
				l = &LikeExpr{E: l, Pat: r, Regexp: true}
				continue
			}
			break
		}
		if t.Type == TokPunct {
			switch t.Text {
			case "=", "==", "<>", "!=", "<", "<=", ">", ">=":
				p.next()
				p.skipSpace()
				r, err := p.parseAdd()
				if err != nil {
					return nil, err
				}
				l = &BinOp{Op: t.Text, L: l, R: r}
				continue
			case "||":
				p.next()
				p.skipSpace()
				r, err := p.parseAdd()
				if err != nil {
					return nil, err
				}
				l = &BinOp{Op: "||", L: l, R: r}
				continue
			}
		}
		break
	}
	return l, nil
}

func (p *Parser) parseInBody(l Expr, not bool) (Expr, error) {
	if p.isPunct("(") {
		// could be a subquery or a list
		save := p.pos
		p.next()
		p.skipSpace()
		if p.isKw("SELECT") || p.isKw("WITH") {
			sub, err := p.parseSelect()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &InExpr{E: l, Sel: sub, Not: not}, nil
		}
		p.pos = save
	}
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	var list []Expr
	p.skipSpace()
	if p.isPunct(")") {
		p.next()
		return &InExpr{E: l, List: list, Not: not}, nil
	}
	for {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		list = append(list, e)
		if p.acceptPunct(",") {
			p.skipSpace()
			continue
		}
		break
	}
	if err := p.expectPunct(")"); err != nil {
		return nil, err
	}
	return &InExpr{E: l, List: list, Not: not}, nil
}

func (p *Parser) parseBetweenBody(l Expr, not bool) (Expr, error) {
	lo, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	if !p.acceptKw("AND") {
		return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
	}
	p.skipSpace()
	hi, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	return &BetweenExpr{E: l, Lo: lo, Hi: hi, Not: not}, nil
}

func (p *Parser) parseLikeBody(l Expr, not, glob bool) (Expr, error) {
	pat, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	esc := Expr(nil)
	if p.acceptKw("ESCAPE") {
		p.skipSpace()
		e, err := p.parseAdd()
		if err != nil {
			return nil, err
		}
		esc = e
	}
	return &LikeExpr{E: l, Pat: pat, Esc: esc, Not: not, Glob: glob}, nil
}

func (p *Parser) parseAdd() (Expr, error) {
	l, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for {
		p.skipSpace()
		t := p.cur()
		if t.Type == TokPunct && (t.Text == "+" || t.Text == "-") {
			p.next()
			p.skipSpace()
			r, err := p.parseMul()
			if err != nil {
				return nil, err
			}
			l = &BinOp{Op: t.Text, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func (p *Parser) parseMul() (Expr, error) {
	l, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		p.skipSpace()
		t := p.cur()
		if t.Type == TokPunct && (t.Text == "*" || t.Text == "/" || t.Text == "%") {
			// avoid treating "*" as select star in ambiguous cases: here it is binary
			p.next()
			p.skipSpace()
			r, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			l = &BinOp{Op: t.Text, L: l, R: r}
			continue
		}
		break
	}
	return l, nil
}

func (p *Parser) parseUnary() (Expr, error) {
	t := p.cur()
	if t.Type == TokPunct && (t.Text == "-" || t.Text == "+" || t.Text == "~") {
		p.next()
		p.skipSpace()
		e, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &UnaryOp{Op: t.Text, E: e}, nil
	}
	return p.parsePrimary()
}

func (p *Parser) parsePrimary() (Expr, error) {
	t := p.cur()
	switch t.Type {
	case TokNum:
		p.next()
		return p.numLit(t.Text), nil
	case TokStr:
		p.next()
		return &LitVal{Val: TextValue(t.Text)}, nil
	case TokBlob:
		p.next()
		return &LitVal{Val: BlobValue(hexDecode(t.Text))}, nil
	case TokParam:
		p.next()
		return &ParamExpr{Text: t.Text}, nil
	case TokPunct:
		if t.Text == "(" {
			p.next()
			p.skipSpace()
			if p.isKw("SELECT") || p.isKw("WITH") {
				sub, err := p.parseSelect()
				if err != nil {
					return nil, err
				}
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
				return &SubqExpr{Sel: sub}, nil
			}
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return e, nil
		}
		if t.Text == "*" {
			p.next()
			return &StarRef{}, nil
		}
	case TokIdent:
		lt := strings.ToLower(t.Text)
		switch lt {
		case "null":
			p.next()
			return &LitVal{Val: NullValue()}, nil
		case "true":
			p.next()
			return &LitVal{Val: IntValue(1)}, nil
		case "false":
			p.next()
			return &LitVal{Val: IntValue(0)}, nil
		case "case":
			return p.parseCase()
		case "cast":
			p.next()
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			p.skipSpace()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.acceptKw("AS") {
				return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
			}
			p.skipSpace()
			var sb strings.Builder
			for {
				ct := p.cur()
				if ct.Type == TokIdent {
					sb.WriteString(ct.Text)
					p.next()
				} else if ct.Type == TokPunct && (ct.Text == "(" || ct.Text == ")") {
					sb.WriteString(ct.Text)
					p.next()
					if ct.Text == ")" {
						break
					}
				} else {
					break
				}
				if p.cur().Type == TokSpace {
					break
				}
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &CastExpr{E: e, Type: sb.String()}, nil
		case "exists":
			p.next()
			p.skipSpace()
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			p.skipSpace()
			sub, err := p.parseSelect()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &ExistsExpr{Sel: sub}, nil
		case "not":
			// handled in parseNot
		}
		// function call?
		save := p.pos
		p.next()
		p.skipSpace()
		if p.isPunct("(") {
			name := t.Text
			p.next()
			p.skipSpace()
			fn := &FuncExpr{Name: strings.ToLower(name)}
			if p.isPunct("*") {
				p.next()
				fn.Star = true
			} else if p.acceptKw("DISTINCT") {
				fn.Distinct = true
				p.skipSpace()
				for {
					a, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					fn.Args = append(fn.Args, a)
					if p.acceptPunct(",") {
						p.skipSpace()
						continue
					}
					break
				}
			} else if !p.isPunct(")") {
				for {
					a, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					fn.Args = append(fn.Args, a)
					if p.acceptPunct(",") {
						p.skipSpace()
						continue
					}
					break
				}
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return fn, nil
		}
		p.pos = save
		// column reference
		p.next()
		p.skipSpace()
		if p.isPunct(".") {
			// qualified: a.b or a.b.c
			p.next()
			p.skipSpace()
			nt := p.cur()
			if nt.Type == TokIdent {
				p.next()
				p.skipSpace()
				if p.isPunct(".") {
					p.next()
					p.skipSpace()
					nt2 := p.cur()
					if nt2.Type == TokIdent {
						p.next()
						return &ColRef{Table: nt.Text, Name: nt2.Text, Raw: t.Text + "." + nt.Text + "." + nt2.Text}, nil
					}
					return &ColRef{Table: nt.Text, Name: "*", Raw: t.Text + "." + nt.Text + ".*"}, nil
				}
				return &ColRef{Table: t.Text, Name: nt.Text, Raw: t.Text + "." + nt.Text}, nil
			}
			if nt.Type == TokPunct && nt.Text == "*" {
				p.next()
				return &StarRef{Table: t.Text}, nil
			}
		}
		return &ColRef{Name: t.Text, Raw: t.Text}, nil
	}
	return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
}

func (p *Parser) parseCase() (Expr, error) {
	p.next() // CASE
	p.skipSpace()
	ce := &CaseExpr{}
	if !p.isKw("WHEN") {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		ce.Base = e
	}
	for p.isKw("WHEN") {
		p.next()
		p.skipSpace()
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.acceptKw("THEN") {
			return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
		}
		p.skipSpace()
		t2, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		ce.Whens = append(ce.Whens, WhenClause{When: w, Then: t2})
	}
	if p.acceptKw("ELSE") {
		p.skipSpace()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		ce.Else = e
	}
	if !p.acceptKw("END") {
		return nil, fmt.Errorf("near %q: syntax error", p.cur().Raw)
	}
	return ce, nil
}

func (p *Parser) numLit(s string) Expr {
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		if i, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return &LitVal{Val: IntValue(i)}
		}
		return &LitVal{Val: IntValue(0)}
	}
	if !strings.ContainsAny(s, ".eE") {
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return &LitVal{Val: IntValue(i)}
		}
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return &LitVal{Val: IntValue(0)}
	}
	return &LitVal{Val: RealValue(f)}
}

func hexDecode(s string) string {
	var sb strings.Builder
	for i := 0; i+1 < len(s); i += 2 {
		hi := hexVal(s[i])
		lo := hexVal(s[i+1])
		sb.WriteByte(byte(hi<<4 | lo))
	}
	return sb.String()
}

func hexVal(c byte) int {
	if c >= '0' && c <= '9' {
		return int(c - '0')
	}
	if c >= 'a' && c <= 'f' {
		return int(c-'a') + 10
	}
	return int(c-'A') + 10
}
