		case ">":
			res = c > 0
		case ">=":
			res = c >= 0
		}
		if res {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case "+", "-", "*", "/", "%":
		if lv.T == VNull || rv.T == VNull {
			return NullValue(), 0
		}
		ln := lv.ToNum()
		rn := rv.ToNum()
		if ln.T == VNull || rn.T == VNull {
