		}
		// at least one real
		a := ln.ToReal()
		b := rn.ToReal()
		switch node.Op {
		case "+":
			return RealValue(a + b), 0
		case "-":
			return RealValue(a - b), 0
		case "*":
			return RealValue(a * b), 0
		case "/":
			if b == 0 {
				return NullValue(), 0
			}
			return RealValue(a / b), 0
		}
	}
	return NullValue(), 0
}

func (v Value) IsZeroNum() bool {
	if v.T == VInt {
		return v.I == 0
	}
	if v.T == VReal {
		return v.F == 0
	}
	return false
}

func (e *Env) evalIn(node *InExpr) (Value, int) {
	v, aff := e.eval(node.E)
	var vals []Value
	if node.Sel != nil {
		rs, err := e.DB.runSelect(node.Sel, e.CTEs)
		if err != nil {
			e.setError(err)
			return NullValue(), 0
		}
		for _, r := range rs.Rows {
			if len(r) > 0 {
				vals = append(vals, r[0])
			}
		}
	} else {
		for _, ex := range node.List {
			v2, _ := e.eval(ex)
			vals = append(vals, v2)
		}
	}
	if v.T == VNull {
		return NullValue(), 0
	}
	if len(vals) == 0 {
		if node.Not {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	}
	found := false
	hasNull := false
	for _, x := range vals {
		if x.T == VNull {
			hasNull = true
			continue
		}
		if cmpAff(v, aff, x, 0) == 0 {
			found = true
			break
		}
	}
	var r int
	if found {
		r = 1
	} else if hasNull {
		return NullValue(), 0
	}
	if node.Not {
		if r == 1 {
			return IntValue(0), 0
		}
		return IntValue(1), 0
	}
	return IntValue(int64(r)), 0
}

func (e *Env) evalLike(node *LikeExpr) (Value, int) {
	v, _ := e.eval(node.E)
	p, _ := e.eval(node.Pat)
	if v.T == VNull || p.T == VNull {
		return NullValue(), 0
	}
	s := v.ToText()
	pat := p.ToText()
	esc := ""
	if node.Esc != nil {
		ev, _ := e.eval(node.Esc)
		esc = ev.ToText()
	}
	var ok bool
	if node.Glob {
		ok = globMatch(pat, s, esc)
	} else if node.Regexp {
		ok = regexpMatch(pat, s)
	} else {
		ok = likeMatch(pat, s, esc)
	}
	r := 0
	if ok {
		r = 1
	}
	if node.Not {
		if r == 1 {
			return IntValue(0), 0
		}
		return IntValue(1), 0
	}
	return IntValue(int64(r)), 0
}

func likeMatch(pat, s, esc string) bool {
	// case-insensitive ASCII
	lp := strings.ToLower(pat)
	ls := strings.ToLower(s)
	return likeRec(lp, ls, esc)
}

func likeRec(p, s, esc string) bool {
	for len(p) > 0 {
		if esc != "" && strings.HasPrefix(p, esc) {
			if len(p) <= len(esc) {
				return false
			}
			p = p[len(esc):]
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
			continue
		}
		switch p[0] {
		case '%':
			for len(p) > 0 && p[0] == '%' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(s); i++ {
				if likeRec(p, s[i:], esc) {
					return true
				}
			}
			return false
		case '_':
			if len(s) == 0 {
				return false
			}
			_, sz := utf8Decode(s)
			p = p[1:]
			s = s[sz:]
		default:
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
		}
	}
	return len(s) == 0
}

func globMatch(pat, s, esc string) bool {
	return globRec(pat, s, esc)
}

func globRec(p, s, esc string) bool {
	for len(p) > 0 {
		if esc != "" && strings.HasPrefix(p, esc) {
			if len(p) <= len(esc) {
				return false
			}
			p = p[len(esc):]
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
			continue
		}
		switch p[0] {
		case '*':
			for len(p) > 0 && p[0] == '*' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(s); i++ {
				if globRec(p, s[i:], esc) {
					return true
				}
			}
			return false
		case '?':
			if len(s) == 0 {
				return false
			}
			_, sz := utf8Decode(s)
			p = p[1:]
			s = s[sz:]
		case '[':
			// character class
			j := 1
			neg := false
			if j < len(p) && (p[j] == '^') {
				neg = true
				j++
			}
			first := true
			matched := false
			var rch rune
			if len(s) > 0 {
				rch, _ = utf8.DecodeRuneInString(s)
			}
			for {
				if j >= len(p) {
					return false
				}
				if p[j] == ']' && !first {
					break
				}
				first = false
				if p[j] == '[' && j+1 < len(p) && (p[j+1] == ':' || p[j+1] == '.' || p[j+1] == '=') {
					// character class like [:alpha:]
					end := strings.Index(p[j+1:], ":]")
					if p[j+1] == ':' && end >= 0 {
						name := p[j+2 : j+1+end]
						if len(s) > 0 && classMatch(name, rch) {
							matched = true
						}
						j = j + 1 + end + 2
						continue
					}
				}
				lo := p[j]
				hi := lo
				if j+2 < len(p) && p[j+1] == '-' && p[j+2] != ']' {
					hi = p[j+2]
					j += 2
				}
				if len(s) > 0 && byte(rch) >= lo && byte(rch) <= hi {
					matched = true
				}
				j++
			}
			if j < len(p) {
				j++ // skip ]
			}
			if neg {
				matched = !matched
			}
			if !matched {
				return false
			}
			if len(s) == 0 {
				return false
			}
			_, sz := utf8.DecodeRuneInString(s)
			s = s[sz:]
			p = p[j:]
		default:
			if len(s) == 0 || s[0] != p[0] {
				return false
			}
			p = p[1:]
			s = s[1:]
		}
	}
	return len(s) == 0
}

func classMatch(name string, r rune) bool {
	switch name {
	case "alpha":
		return unicodeIsLetter(r)
	case "digit":
		return unicodeIsDigit(r)
	case "alnum":
		return unicodeIsLetter(r) || unicodeIsDigit(r)
	case "space":
		return unicodeIsSpace(r)
	case "xdigit":
		return unicodeIsHexDigit(r)
	case "lower":
		return unicodeIsLower(r)
	case "upper":
		return unicodeIsUpper(r)
	case "punct":
		return unicodeIsPunct(r)
	}
	return false
}

func regexpMatch(pat, s string) bool {
	re, err := compileRegexp(pat)
	if err != nil {
		return false
	}
	return re.MatchString(s)
}

func castValue(v Value, typ string) Value {
	t := strings.ToUpper(strings.TrimSpace(typ))
	base := t
	if i := strings.Index(t, "("); i >= 0 {
		base = t[:i]
	}
	switch strings.TrimSpace(base) {
	case "", "TEXT", "VARCHAR", "NVARCHAR", "CHAR", "NCHAR", "CLOB", "NVARCHAR2", "STRING":
		if v.T == VNull {
			return NullValue()
		}
		return TextValue(v.ToText())
	case "INTEGER", "INT", "BIGINT", "SMALLINT", "TINYINT", "MEDIUMINT", "INT2", "INT4", "INT8":
		if v.T == VNull {
			return NullValue()
		}
		if v.T == VText {
			s := strings.TrimSpace(v.S)
			if i, err := strconvParseInt(s); err == nil {
				return IntValue(i)
			}
			// SQLite: parse the longest numeric prefix
			if f, err := strconvParseFloat(prefix(s)); err == nil {
				return IntValue(int64(f))
			}
			return IntValue(0)
		}
		if v.T == VReal {
			return IntValue(int64(v.F))
		}
		return IntValue(v.ToInt())
	case "REAL", "FLOAT", "DOUBLE", "DOUBLE PRECISION", "NUMERIC", "DECIMAL":
		if v.T == VNull {
			return NullValue()
		}
		if v.T == VInt {
			return RealValue(float64(v.I))
		}
		if v.T == VReal {
			return v
		}
		f, err := strconvParseFloat(prefix(strings.TrimSpace(v.S)))
		if err != nil {
			return RealValue(0)
		}
		return RealValue(f)
	case "BLOB":
		return BlobValue(v.ToText())
	}
	return v
}

func prefix(s string) string {
	i := 0
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		i++
	}
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i < len(s) && s[i] == '.' {
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		k := j
		for k < len(s) && s[k] >= '0' && s[k] <= '9' {
			k++
		}
		if k > j {
			i = k
		}
	}
	return s[:i]
}

func sortRows(rs [][]Value, less func(a, b []Value) bool) {
	sort.SliceStable(rs, func(i, j int) bool { return less(rs[i], rs[j]) })
}
EOF
