package main

import (
	"fmt"
	"sort"
	"strings"
)

// Table is a materialized table.
type Table struct {
	Name string
	Cols []string
	Rows [][]Value
	idx  map[string][]int // lower name -> column indexes
}

func newTable(name string, cols []string) *Table {
	t := &Table{Name: name, Cols: cols}
	t.build()
	return t
}

func (t *Table) build() {
	t.idx = make(map[string][]int)
	for i, c := range t.Cols {
		k := strings.ToLower(c)
		t.idx[k] = append(t.idx[k], i)
	}
}

func (t *Table) colIndex(name string) (int, bool) {
	v, ok := t.idx[strings.ToLower(name)]
	if !ok || len(v) == 0 {
		return 0, false
	}
	return v[0], true
}

// DB holds tables created by the importer and CTEs.
type DB struct {
	tables map[string]*Table
	order  []string
}

func NewDB() *DB {
	return &DB{tables: make(map[string]*Table)}
}

func (db *DB) Add(t *Table) {
	key := strings.ToLower(t.Name)
	if _, ok := db.tables[key]; !ok {
		db.order = append(db.order, key)
	}
	db.tables[key] = t
}

func (db *DB) Get(name string) (*Table, bool) {
	t, ok := db.tables[strings.ToLower(name)]
	return t, ok
}

func (db *DB) Names() []string {
	var out []string
	for _, k := range db.order {
		out = append(out, db.tables[k].Name)
	}
	return out
}

// ResultSet is the result of a query.
type ResultSet struct {
	Cols []string
	Rows [][]Value
}

// ColInfo describes a column in the evaluation context.
type ColInfo struct {
	Table string
	Name  string
	Lower string
	Affin int // 0 none, 1 text, 2 numeric
}

// RowCtx is the evaluation context for a row.
type RowCtx struct {
	Cols []ColInfo
	Vals []Value
}

func (c *RowCtx) find(table, name string) (int, bool) {
	if table == "" {
		ln := strings.ToLower(name)
		for i := range c.Cols {
			if c.Cols[i].Lower == ln {
				return i, true
			}
		}
		return 0, false
	}
	lt := strings.ToLower(table)
	ln := strings.ToLower(name)
	for i := range c.Cols {
		if strings.EqualFold(c.Cols[i].Table, table) && c.Cols[i].Lower == ln {
			return i, true
		}
	}
	return 0, false
}

// Env holds evaluation state.
type Env struct {
	DB      *DB
	Row     *RowCtx
	CTEs    map[string]*Table
	Groups  *GroupState
	Rownum  int
	Params  map[string]Value
	Err     error
}

// GroupState is used while computing aggregates.
type GroupState struct {
	Rows []*RowCtx
}

func (e *Env) setError(err error) {
	if e.Err == nil {
		e.Err = err
	}
}

// Eval evaluates an expression in the current environment.
func (e *Env) Eval(ex Expr) Value {
	v, _ := e.eval(ex)
	return v
}

func (e *Env) eval(ex Expr) (Value, int) {
	if ex == nil {
		return NullValue(), 0
	}
	switch node := ex.(type) {
	case *LitVal:
		return node.Val, 0
	case *ParamExpr:
		if e.Params != nil {
			if v, ok := e.Params[node.Text]; ok {
				return v, 0
			}
		}
		return NullValue(), 0
	case *ColRef:
		if e.Row == nil {
			return NullValue(), 0
		}
		i, ok := e.Row.find(node.Table, node.Name)
		if !ok {
			key := node.Name
			if node.Table != "" {
				key = node.Table + "." + node.Name
			}
			e.setError(fmt.Errorf("no such column: %s", key))
			return NullValue(), 0
		}
		return e.Row.Vals[i], e.Row.Cols[i].Affin
	case *StarRef:
		return NullValue(), 0
	case *UnaryOp:
		v, _ := e.eval(node.E)
		switch node.Op {
		case "-":
			if v.T == VNull {
				return NullValue(), 0
			}
			n := v.ToNum()
			if n.T == VInt {
				return IntValue(-n.I), 0
			}
			return RealValue(-n.F), 0
		case "+":
			if v.T == VNull {
				return NullValue(), 0
			}
			return v.ToNum(), 0
		case "~":
			if v.T == VNull {
				return NullValue(), 0
			}
			return IntValue(^v.ToInt()), 0
		case "NOT":
			b := truthy(v)
			if b < 0 {
				return NullValue(), 0
			}
			if b == 1 {
				return IntValue(0), 0
			}
			return IntValue(1), 0
		}
		return NullValue(), 0
	case *BinOp:
		return e.evalBin(node)
	case *CaseExpr:
		var base Value
		hasBase := node.Base != nil
		if hasBase {
			base, _ = e.eval(node.Base)
		}
		for _, w := range node.Whens {
			cv, _ := e.eval(w.When)
			var match bool
			if hasBase {
				match = !base.T_isNull() && !cv.T_isNull() && cmpAff(base, 0, cv, 0) == 0
			} else {
				match = truthy(cv) == 1
			}
			if match {
				return e.eval(w.Then)
			}
		}
		if node.Else != nil {
			return e.eval(node.Else)
		}
		return NullValue(), 0
	case *InExpr:
		return e.evalIn(node)
	case *BetweenExpr:
		v, _ := e.eval(node.E)
		lo, _ := e.eval(node.Lo)
		hi, _ := e.eval(node.Hi)
		if v.T == VNull || lo.T == VNull || hi.T == VNull {
			return NullValue(), 0
		}
		r := 0
		if cmpAff(v, 0, lo, 0) >= 0 && cmpAff(v, 0, hi, 0) <= 0 {
			r = 1
		}
		if node.Not {
			if r == 1 {
				return IntValue(0), 0
			}
			return IntValue(1), 0
		}
		return IntValue(int64(r)), 0
	case *LikeExpr:
		return e.evalLike(node)
	case *IsExpr:
		v, _ := e.eval(node.E)
		r, _ := e.eval(node.Val)
		if v.T == VNull || r.T == VNull {
			return NullValue(), 0
		}
		if cmpAff(v, 0, r, 0) == 0 {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case *NullExpr:
		v, _ := e.eval(node.E)
		isNull := v.T == VNull
		res := isNull
		if node.Not {
			res = !isNull
		}
		if res {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case *SubqExpr:
		rs, err := e.DB.runSelect(node.Sel, e.CTEs)
		if err != nil {
			e.setError(err)
			return NullValue(), 0
		}
		if len(rs.Rows) == 0 || len(rs.Rows[0]) == 0 {
			return NullValue(), 0
		}
		return rs.Rows[0][0], 0
	case *ExistsExpr:
		rs, err := e.DB.runSelect(node.Sel, e.CTEs)
		if err != nil {
			e.setError(err)
			return NullValue(), 0
		}
		if len(rs.Rows) > 0 {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case *CastExpr:
		v, _ := e.eval(node.E)
		return castValue(v, node.Type), 0
	case *CollateExpr:
		v, _ := e.eval(node.E)
		return v, 0
	case *FuncExpr:
		return e.evalFunc(node)
	}
	return NullValue(), 0
}

func (v Value) T_isNull() bool { return v.T == VNull }

// cmpAff compares two values with affinity consideration.
func cmpAff(a Value, affA, b Value, affB int) int {
	// apply affinity: if one side is text-affine and the other side is a plain
	// numeric literal (no affinity), convert the literal to text.
	if affA == 1 && affB == 0 && b.IsNum() {
		b = TextValue(b.ToText())
	} else if affB == 1 && affA == 0 && a.IsNum() {
		a = TextValue(a.ToText())
	}
	if a.T == VNull || b.T == VNull {
		if a.T == VNull && b.T == VNull {
			return 0
		}
		if a.T == VNull {
			return -1
		}
		return 1
	}
	return a.CmpRaw(b)
}

func truthy(v Value) int {
	switch v.T {
	case VNull:
		return -1
	case VInt:
		if v.I != 0 {
			return 1
		}
	case VReal:
		if v.F != 0 {
			return 1
		}
	default:
		s := strings.TrimSpace(v.S)
		if f, err := strconvParse(s); err == nil {
			if f != 0 {
				return 1
			}
		}
	}
	return 0
}

func strconvParse(s string) (float64, error) {
	if s == "" {
		return 0, errNotNum
	}
	var f float64
	var err error
	if i, e := parseIntStr(s); e == nil {
		return float64(i), nil
	}
	f, err = parseFloatStr(s)
	return f, err
}

func (e *Env) evalBin(node *BinOp) (Value, int) {
	switch node.Op {
	case "AND":
		l, _ := e.eval(node.L)
		tl := truthy(l)
		if tl == 0 {
			return IntValue(0), 0
		}
		r, _ := e.eval(node.R)
		tr := truthy(r)
		if tr == 0 {
			return IntValue(0), 0
		}
		if tl < 0 || tr < 0 {
			return NullValue(), 0
		}
		return IntValue(1), 0
	case "OR":
		l, _ := e.eval(node.L)
		tl := truthy(l)
		if tl == 1 {
			return IntValue(1), 0
		}
		r, _ := e.eval(node.R)
		tr := truthy(r)
		if tr == 1 {
			return IntValue(1), 0
		}
		if tl < 0 || tr < 0 {
			return NullValue(), 0
		}
		return IntValue(0), 0
	}
	lv, affL := e.eval(node.L)
	rv, affR := e.eval(node.R)
	switch node.Op {
	case "||":
		if lv.T == VNull || rv.T == VNull {
			return NullValue(), 0
		}
		return TextValue(lv.ToText() + rv.ToText()), 0
	case "=", "==", "<>", "!=", "<", "<=", ">", ">=":
		if lv.T == VNull || rv.T == VNull {
			return NullValue(), 0
		}
		c := cmpAff(lv, affL, rv, affR)
		var res bool
		switch node.Op {
		case "=", "==":
			res = c == 0
		case "<>", "!=":
			res = c != 0
		case "<":
			res = c < 0
		case "<=":
			res = c <= 0
		case ">":
			res = c > 0
		case ">=":
			res = c >= 0
		}
		if res {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case "+", "-", "*", "/", "%":
		if lv.T == VNull || rv.T == VNull {
			return NullValue(), 0
		}
		ln := lv.ToNum()
		rn := rv.ToNum()
		if ln.T == VNull || rn.T == VNull {
			// text that is not numeric becomes 0
		}
		if node.Op == "%" {
			if rn.IsZeroNum() {
				return NullValue(), 0
			}
			li := ln.ToInt()
			ri := rn.ToInt()
			if ri == 0 {
				return NullValue(), 0
			}
			return IntValue(li % ri), 0
		}
		if ln.T == VInt && rn.T == VInt {
			switch node.Op {
			case "+":
				return IntValue(ln.I + rn.I), 0
			case "-":
				return IntValue(ln.I - rn.I), 0
			case "*":
				return IntValue(ln.I * rn.I), 0
			case "/":
				if rn.I == 0 {
					return NullValue(), 0
				}
				return IntValue(ln.I / rn.I), 0
			}
		}
		// at least one real
		a := ln.ToReal()
		b := rn.ToReal()
		switch node.Op {
		case "+":
			return RealValue(a + b), 0
		case "-":
			return RealValue(a - b), 0
		case "*":
			return RealValue(a * b), 0
		case "/":
			if b == 0 {
				return NullValue(), 0
			}
			return RealValue(a / b), 0
		}
	}
	return NullValue(), 0
}

func (v Value) IsZeroNum() bool {
	if v.T == VInt {
		return v.I == 0
	}
	if v.T == VReal {
		return v.F == 0
	}
	return false
}

func (e *Env) evalIn(node *InExpr) (Value, int) {
	v, aff := e.eval(node.E)
	var vals []Value
	if node.Sel != nil {
		rs, err := e.DB.runSelect(node.Sel, e.CTEs)
		if err != nil {
			e.setError(err)
			return NullValue(), 0
		}
		for _, r := range rs.Rows {
			if len(r) > 0 {
				vals = append(vals, r[0])
			}
		}
	} else {
		for _, ex := range node.List {
			v2, _ := e.eval(ex)
			vals = append(vals, v2)
		}
	}
	if v.T == VNull {
		return NullValue(), 0
	}
	if len(vals) == 0 {
		if node.Not {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	}
	found := false
	hasNull := false
	for _, x := range vals {
		if x.T == VNull {
			hasNull = true
			continue
		}
		if cmpAff(v, aff, x, 0) == 0 {
			found = true
			break
		}
	}
	var r int
	if found {
		r = 1
	} else if hasNull {
		return NullValue(), 0
	}
	if node.Not {
		if r == 1 {
			return IntValue(0), 0
		}
		return IntValue(1), 0
	}
	return IntValue(int64(r)), 0
}

func (e *Env) evalLike(node *LikeExpr) (Value, int) {
	v, _ := e.eval(node.E)
	p, _ := e.eval(node.Pat)
	if v.T == VNull || p.T == VNull {
		return NullValue(), 0
	}
	s := v.ToText()
	pat := p.ToText()
	esc := ""
	if node.Esc != nil {
		ev, _ := e.eval(node.Esc)
		esc = ev.ToText()
	}
	var ok bool
	if node.Glob {
		ok = globMatch(pat, s, esc)
	} else if node.Regexp {
		ok = regexpMatch(pat, s)
	} else {
		ok = likeMatch(pat, s, esc)
	}
	r := 0
	if ok {
		r = 1
	}
	if node.Not {
		if r == 1 {
			return IntValue(0), 0
		}
		return IntValue(1), 0
	}
	return IntValue(int64(r)), 0
}

func likeMatch(pat, s, esc string) bool {
	// case-insensitive ASCII
	lp := strings.ToLower(pat)
	ls := strings.ToLower(s)
	return likeRec(lp, ls, esc)
}

func likeRec(p, s, esc string) bool {
	for len(p) > 0 {
		if esc != "" && strings.HasPrefix(p, esc) {
			if len(p) <= len(esc) {
				return false
			}
			p = p[len(esc):]
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
			continue
		}
		switch p[0] {
		case '%':
			for len(p) > 0 && p[0] == '%' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(s); i++ {
				if likeRec(p, s[i:], esc) {
					return true
				}
			}
			return false
		case '_':
			if len(s) == 0 {
				return false
			}
			_, sz := utf8Decode(s)
			p = p[1:]
			s = s[sz:]
		default:
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
		}
	}
	return len(s) == 0
}

func globMatch(pat, s, esc string) bool {
	return globRec(pat, s, esc)
}

func globRec(p, s, esc string) bool {
	for len(p) > 0 {
		if esc != "" && strings.HasPrefix(p, esc) {
			if len(p) <= len(esc) {
				return false
			}
			p = p[len(esc):]
			r, sz := utf8Decode(p)
			if len(s) < sz || s[:sz] != p[:sz] {
				return false
			}
			p = p[sz:]
			s = s[sz:]
			continue
		}
		switch p[0] {
		case '*':
			for len(p) > 0 && p[0] == '*' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(s); i++ {
				if globRec(p, s[i:], esc) {
					return true
				}
			}
			return false
		case '?':
			if len(s) == 0 {
				return false
			}
			_, sz := utf8Decode(s)
			p = p[1:]
			s = s[sz:]
		case '[':
			// character class
			j := 1
			neg := false
			if j < len(p) && (p[j] == '^') {
				neg = true
				j++
			}
			first := true
			matched := false
			var rch rune
			if len(s) > 0 {
				rch, _ = utf8.DecodeRuneInString(s)
			}
			for {
				if j >= len(p) {
					return false
				}
				if p[j] == ']' && !first {
					break
				}
				first = false
				if p[j] == '[' && j+1 < len(p) && (p[j+1] == ':' || p[j+1] == '.' || p[j+1] == '=') {
					// character class like [:alpha:]
					end := strings.Index(p[j+1:], ":]")
					if p[j+1] == ':' && end >= 0 {
						name := p[j+2 : j+1+end]
						if len(s) > 0 && classMatch(name, rch) {
							matched = true
						}
						j = j + 1 + end + 2
						continue
					}
				}
				lo := p[j]
				hi := lo
				if j+2 < len(p) && p[j+1] == '-' && p[j+2] != ']' {
					hi = p[j+2]
					j += 2
				}
				if len(s) > 0 && byte(rch) >= lo && byte(rch) <= hi {
					matched = true
				}
				j++
			}
			if j < len(p) {
				j++ // skip ]
			}
			if neg {
				matched = !matched
			}
			if !matched {
				return false
			}
			if len(s) == 0 {
				return false
			}
			_, sz := utf8.DecodeRuneInString(s)
			s = s[sz:]
			p = p[j:]
		default:
			if len(s) == 0 || s[0] != p[0] {
				return false
			}
			p = p[1:]
			s = s[1:]
		}
	}
	return len(s) == 0
}

func classMatch(name string, r rune) bool {
	switch name {
	case "alpha":
		return unicodeIsLetter(r)
	case "digit":
		return unicodeIsDigit(r)
	case "alnum":
		return unicodeIsLetter(r) || unicodeIsDigit(r)
	case "space":
		return unicodeIsSpace(r)
	case "xdigit":
		return unicodeIsHexDigit(r)
	case "lower":
		return unicodeIsLower(r)
	case "upper":
		return unicodeIsUpper(r)
	case "punct":
		return unicodeIsPunct(r)
	}
	return false
}

func regexpMatch(pat, s string) bool {
	re, err := compileRegexp(pat)
	if err != nil {
		return false
	}
	return re.MatchString(s)
}

func castValue(v Value, typ string) Value {
	t := strings.ToUpper(strings.TrimSpace(typ))
	base := t
	if i := strings.Index(t, "("); i >= 0 {
		base = t[:i]
	}
	switch strings.TrimSpace(base) {
	case "", "TEXT", "VARCHAR", "NVARCHAR", "CHAR", "NCHAR", "CLOB", "NVARCHAR2", "STRING":
		if v.T == VNull {
			return NullValue()
		}
		return TextValue(v.ToText())
	case "INTEGER", "INT", "BIGINT", "SMALLINT", "TINYINT", "MEDIUMINT", "INT2", "INT4", "INT8":
		if v.T == VNull {
			return NullValue()
		}
		if v.T == VText {
			s := strings.TrimSpace(v.S)
			if i, err := strconvParseInt(s); err == nil {
				return IntValue(i)
			}
			// SQLite: parse the longest numeric prefix
			if f, err := strconvParseFloat(prefix(s)); err == nil {
				return IntValue(int64(f))
			}
			return IntValue(0)
		}
		if v.T == VReal {
			return IntValue(int64(v.F))
		}
		return IntValue(v.ToInt())
	case "REAL", "FLOAT", "DOUBLE", "DOUBLE PRECISION", "NUMERIC", "DECIMAL":
		if v.T == VNull {
			return NullValue()
		}
		if v.T == VInt {
			return RealValue(float64(v.I))
		}
		if v.T == VReal {
			return v
		}
		f, err := strconvParseFloat(prefix(strings.TrimSpace(v.S)))
		if err != nil {
			return RealValue(0)
		}
		return RealValue(f)
	case "BLOB":
		return BlobValue(v.ToText())
	}
	return v
}

func prefix(s string) string {
	i := 0
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		i++
	}
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i < len(s) && s[i] == '.' {
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		k := j
		for k < len(s) && s[k] >= '0' && s[k] <= '9' {
			k++
		}
		if k > j {
			i = k
		}
	}
	return s[:i]
}

func sortRows(rs [][]Value, less func(a, b []Value) bool) {
	sort.SliceStable(rs, func(i, j int) bool { return less(rs[i], rs[j]) })
}
