	case VInt:
		if v.I != 0 {
			return 1
		}
	case VReal:
		if v.F != 0 {
			return 1
		}
	default:
		s := strings.TrimSpace(v.S)
		if f, err := strconvParse(s); err == nil {
			if f != 0 {
				return 1
			}
		}
	}
	return 0
