{"command": "cd /workspace/trdsql && cat > select.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

// hasAggregate reports whether the expression contains an aggregate call.
func hasAggregate(ex Expr) bool {
	switch node := ex.(type) {
	case nil:
		return false
	case *FuncExpr:
		if isAggName(node.Name) {
			return true
		}
		for _, a := range node.Args {
			if hasAggregate(a) {
				return true
			}
		}
		return false
	case *BinOp:
		return hasAggregate(node.L) || hasAggregate(node.R)
	case *UnaryOp:
		return hasAggregate(node.E)
	case *CaseExpr:
		if hasAggregate(node.Base) || hasAggregate(node.Else) {
			return true
		}
		for _, w := range node.Whens {
			if hasAggregate(w.When) || hasAggregate(w.Then) {
				return true
			}
		}
		return false
	case *InExpr:
		if hasAggregate(node.E) {
			return true
		}
		for _, e := range node.List {
			if hasAggregate(e) {
				return true
			}
		}
		return false
	case *BetweenExpr:
		return hasAggregate(node.E) || hasAggregate(node.Lo) || hasAggregate(node.Hi)
	case *LikeExpr:
		return hasAggregate(node.E) || hasAggregate(node.Pat) || hasAggregate(node.Esc)
	case *IsExpr:
		return hasAggregate(node.E) || hasAggregate(node.Val)
	case *NullExpr:
		return hasAggregate(node.E)
	case *CastExpr:
		return hasAggregate(node.E)
	case *CollateExpr:
		return hasAggregate(node.E)
	}
	return false
}

func isAggName(n string) bool {
	switch n {
	case "count", "sum", "avg", "min", "max", "total", "group_concat", "string_agg", "count_star":
		return true
	}
	return false
}

// runSelect executes a select statement.
func (db *DB) runSelect(sel *Select, parentCTEs map[string]*Table) (*ResultSet, error) {
	ctes := map[string]*Table{}
	for k, v := range parentCTEs {
		ctes[k] = v
	}
	if sel.With != nil {
		for _, c := range sel.With {
			rs, err := db.runSelect(c.Sel, ctes)
			if err != nil {
				return nil, err
			}
			t := newTable(c.Name, rs.Cols)
			t.Rows = rs.Rows
			ctes[strings.ToLower(c.Name)] = t
		}
	}
	// build sources
	type source struct {
		alias string
		table *Table
	}
	var sources []source
	var joinRows []([]*RowCtx)
	baseCtx := &RowCtx{}
	for _, tr := range sel.From {
		var t *Table
		if tr.IsSub {
			rs, err := db.runSelect(tr.Sub, ctes)
			if err != nil {
				return nil, err
			}
			t = newTable("", rs.Cols)
			t.Rows = rs.Rows
		} else {
			name := tr.Name
			if ct, ok := ctes[strings.ToLower(name)]; ok {
				t = ct
			} else if bt, ok := db.Get(name); ok {
				t = bt
			} else {
				return nil, fmt.Errorf("no such table: %s", name)
			}
		}
		alias := tr.Alias
		if alias == "" {
			alias = tr.Name
		}
		sources = append(sources, source{alias: alias, table: t})
	}
	if len(sources) == 0 {
		// SELECT without FROM: single row
		sr := &RowCtx{}
		sr.Vals = []Value{}
		joinRows = [][]*RowCtx{{sr}}
	} else {
		// start with the first source
		first := sources[0]
		base := make([]ColInfo, 0, len(first.table.Cols))
		for _, c := range first.table.Cols {
			base = append(base, ColInfo{Table: first.alias, Name: c, Lower: strings.ToLower(c), Affin: 1})
		}
		rows := make([]*RowCtx, 0, len(first.table.Rows))
		for _, r := range first.table.Rows {
			rc := &RowCtx{Cols: base, Vals: append([]Value{}, r...)}
			rows = append(rows, rc)
		}
		joinRows = rows
	}
	// joins
	for i := 1; i < len(sources); i++ {
		tr := sel.From[i]
		if !tr.HasJoin {
			continue
		}
		src := sources[i]
		cols := make([]ColInfo, 0, len(src.table.Cols))
		for _, c := range src.table.Cols {
			cols = append(cols, ColInfo{Table: src.alias, Name: c, Lower: strings.ToLower(c), Affin: 1})
		}
		var newRows []*RowCtx
		for _, lr := range joinRows {
			var on func(rc *RowCtx) bool
			j := tr.Join
			if j.On != nil {
				on = func(rc *RowCtx) bool {
					env := &Env{DB: db, Row: rc, CTEs: ctes}
					v := env.Eval(j.On)
					return truthy(v) == 1
				}
			}
			matched := false
			for _, r := range src.table.Rows {
				rc := &RowCtx{Cols: append(append([]ColInfo{}, lr.Cols...), cols...), Vals: append(append([]Value{}, lr.Vals...), r...)}
				ok := true
				if j.On != nil {
					ok = on(rc)
				} else if len(j.Using) > 0 {
					ok = true
					for _, u := range j.Using {
						a, okA := lr.find("", u)
						b, okB := rc.find(src.alias, u)
						if !okA || !okB {
							ok = false
							break
						}
						if !lr.Vals[a].Equal(rc.Vals[b]) {
							ok = false
							break
						}
					}
				}
				if ok {
					matched = true
					newRows = append(newRows, rc)
				}
			}
			if !matched && (j.Type == "LEFT" || j.Type == "FULL") {
				nulls := make([]Value, len(cols))
				for k := range nulls {
					nulls[k] = NullValue()
				}
				rc := &RowCtx{Cols: append(append([]ColInfo{}, lr.Cols...), cols...), Vals: append(append([]Value{}, lr.Vals...), nulls...)}
				newRows = append(newRows, rc)
			}
		}
		joinRows = newRows
	}
	// extra comma-separated sources (cross join)
	for i := 1; i < len(sources); i++ {
		tr := sel.From[i]
		if tr.HasJoin {
			continue
		}
		src := sources[i]
		cols := make([]ColInfo, 0, len(src.table.Cols))
		for _, c := range src.table.Cols {
			cols = append(cols, ColInfo{Table: src.alias, Name: c, Lower: strings.ToLower(c), Affin: 1})
		}
		var newRows []*RowCtx
		for _, lr := range joinRows {
			for _, r := range src.table.Rows {
				rc := &RowCtx{Cols: append(append([]ColInfo{}, lr.Cols...), cols...), Vals: append(append([]Value{}, lr.Vals...), r...)}
				newRows = append(newRows, rc)
			}
		}
		joinRows = newRows
	}
	// WHERE
	if sel.Where != nil {
		var filtered []*RowCtx
		for _, rc := range joinRows {
			env := &Env{DB: db, Row: rc, CTEs: ctes}
			if truthy(env.Eval(sel.Where)) == 1 {
				filtered = append(filtered, rc)
			} else if env.Err != nil {
				return nil, env.Err
			}
		}
		joinRows = filtered
	}
	// grouping
	var groups [][]*RowCtx
	if len(sel.Group) > 0 || selHasAgg(sel) {
		if len(sel.Group) > 0 {
			type key struct {
				vals []Value
			}
			idx := map[string]int{}
			var keys []string
			for _, rc := range joinRows {
				var kb strings.Builder
				var kv []Value
				for _, ge := range sel.Group {
					env := &Env{DB: db, Row: rc, CTEs: ctes}
					v := env.Eval(ge)
					if env.Err != nil {
						return nil, env.Err
					}
					kv = append(kv, v)
					kb.WriteString(keyOf(v))
					kb.WriteString("\x00")
				}
				k := kb.String()
				if _, ok := idx[k]; !ok {
					idx[k] = len(groups)
					groups = append(groups, nil)
					keys = append(keys, k)
					groups[idx[k]] = []*RowCtx{rc}
				} else {
					groups[idx[k]] = append(groups[idx[k]], rc)
				}
			}
		} else {
			if len(joinRows) > 0 {
				groups = [][]*RowCtx{joinRows}
			} else {
				groups = [][]*RowCtx{nil}
			}
		}
	}
	// build result
	cols := []string{}
	colExprs := []Expr{}
	var colList []SelectCol
	if len(sel.Cols) == 1 {
		if _, ok := sel.Cols[0].Expr.(*StarRef); ok {
			// expand stars
			for _, src := range sources {
				for _, c := range src.table.Cols {
					colList = append(colList, SelectCol{Expr: &ColRef{Table: src.alias, Name: c}})
				}
			}
			if len(sources) == 0 {
				colList = nil
			}
		} else if cr, ok := sel.Cols[0].Expr.(*ColRef); ok && cr.Name == "*" {
			for _, src := range sources {
				if strings.EqualFold(src.alias, cr.Table) {
					for _, c := range src.table.Cols {
						colList = append(colList, SelectCol{Expr: &ColRef{Table: src.alias, Name: c}})
					}
				}
			}
		} else {
			colList = sel.Cols
		}
	} else {
		for _, c := range sel.Cols {
			if sr, ok := c.Expr.(*StarRef); ok {
				if sr.Table == "" {
					for _, src := range sources {
						for _, cc := range src.table.Cols {
							colList = append(colList, SelectCol{Expr: &ColRef{Table: src.alias, Name: cc}})
						}
					}
				} else {
					for _, src := range sources {
						if strings.EqualFold(src.alias, sr.Table) {
							for _, cc := range src.table.Cols {
								colList = append(colList, SelectCol{Expr: &ColRef{Table: src.alias, Name: cc}})
							}
						}
					}
				}
			} else if cr, ok := c.Expr.(*ColRef); ok && cr.Name == "*" {
				for _, src := range sources {
					if strings.EqualFold(src.alias, cr.Table) {
						for _, cc := range src.table.Cols {
							colList = append(colList, SelectCol{Expr: &ColRef{Table: src.alias, Name: cc}})
						}
					}
				}
			} else {
				colList = append(colList, c)
			}
		}
	}
	for i, c := range colList {
		name := ""
		if c.Alias != "" {
			name = c.Alias
		} else if cr, ok := c.Expr.(*ColRef); ok {
			name = cr.Name
		} else {
			name = exprText(c.Expr)
		}
		_ = i
		cols = append(cols, name)
		colExprs = append(colExprs, c.Expr)
	}
	var rows [][]Value
	if groups != nil {
		for _, g := range groups {
			var base *RowCtx
			if len(g) > 0 {
				base = g[0]
			} else {
				base = &RowCtx{Cols: baseCtx.Cols, Vals: []Value{}}
			}
			env := &Env{DB: db, Row: base, CTEs: ctes, Groups: &GroupState{Rows: g}}
			var row []Value
			for _, ce := range colExprs {
				v := env.Eval(ce)
				if env.Err != nil {
					return nil, env.Err
				}
				row = append(row, v)
			}
			if sel.Having != nil {
				if truthy(env.Eval(sel.Having)) != 1 {
					continue
				}
				if env.Err != nil {
					return nil, env.Err
				}
			}
			rows = append(rows, row)
		}
	} else {
		for _, rc := range joinRows {
			env := &Env{DB: db, Row: rc, CTEs: ctes}
			var row []Value
			for _, ce := range colExprs {
				v := env.Eval(ce)
				if env.Err != nil {
					return nil, env.Err
				}
				row = append(row, v)
			}
			rows = append(rows, row)
		}
	}
	// DISTINCT
	if sel.Distinct {
		seen := map[string]bool{}
		var out [][]Value
		for _, r := range rows {
			k := rowKey(r)
			if !seen[k] {
				seen[k] = true
				out = append(out, r)
			}
		}
		rows = out
	}
	// compound
	if sel.Compound != nil {
		rs, err := db.runSelect(sel.Compound, ctes)
		if err != nil {
			return nil, err
		}
		if len(rs.Cols) > len(cols) {
			cols = rs.Cols
		}
		switch sel.Compound.CompoundOp {
		case "UNION":
			seen := map[string]bool{}
			var out [][]Value
			for _, r := range rows {
				k := rowKey(r)
				if !seen[k] {
					seen[k] = true
					out = append(out, r)
				}
			}
			for _, r := range rs.Rows {
				r = padRow(r, len(cols))
				k := rowKey(r)
				if !seen[k] {
					seen[k] = true
					out = append(out, r)
				}
			}
			rows = out
		case "UNION ALL":
			for _, r := range rs.Rows {
				rows = append(rows, padRow(r, len(cols)))
			}
		case "INTERSECT":
			seen := map[string]bool{}
			for _, r := range rs.Rows {
				seen[rowKey(padRow(r, len(cols)))] = true
			}
			var out [][]Value
			seen2 := map[string]bool{}
			for _, r := range rows {
				k := rowKey(padRow(r, len(cols)))
				if seen[k] && !seen2[k] {
					seen2[k] = true
					out = append(out, padRow(r, len(cols)))
				}
			}
			rows = out
		case "EXCEPT":
			seen := map[string]bool{}
			for _, r := range rs.Rows {
				seen[rowKey(padRow(r, len(cols)))] = true
			}
			var out [][]Value
			for _, r := range rows {
				k := rowKey(padRow(r, len(cols)))
				if !seen[k] {
					out = append(out, padRow(r, len(cols)))
				}
			}
			rows = out
		}
	}
	// ORDER BY
	if len(sel.Order) > 0 {
		if err := sortResult(rows, colList, colExprs, sel.Order, db, ctes, joinRows); err != nil {
			return nil, err
		}
	}
	// LIMIT / OFFSET
	if sel.Limit != nil || sel.Offset != nil {
		var off int64
		if sel.Offset != nil {
			env := &Env{DB: db, CTEs: ctes}
			v := env.Eval(sel.Offset)
			off = v.ToInt()
			if env.Err != nil {
				return nil, env.Err
			}
			if off < 0 {
				off = 0
			}
		}
		if sel.Limit != nil {
			env := &Env{DB: db, CTEs: ctes}
			v := env.Eval(sel.Limit)
			if env.Err != nil {
				return nil, env.Err
			}
			lim := v.ToInt()
			if lim < 0 {
				lim = 0
			}
			if off >= int64(len(rows)) {
				rows = nil
			} else {
				rows = rows[off:]
				if lim < int64(len(rows)) {
					rows = rows[:lim]
				}
			}
		} else {
			if off >= int64(len(rows)) {
				rows = nil
			} else {
				rows = rows[off:]
			}
		}
	}
	return &ResultSet{Cols: cols, Rows: rows}, nil
}

func padRow(r []Value, n int) []Value {
	if len(r) >= n {
		return r[:n]
	}
	out := append([]Value{}, r...)
	for len(out) < n {
		out = append(out, NullValue())
	}
	return out
}

func rowKey(r []Value) string {
	var sb strings.Builder
	for _, v := range r {
		switch v.T {
		case VNull:
			sb.WriteString("\x01")
		case VInt:
			sb.WriteString("i")
			sb.WriteString(fmt.Sprintf("%d", v.I))
		case VReal:
			sb.WriteString("f")
			sb.WriteString(fmt.Sprintf("%v", v.F))
		default:
			sb.WriteString("s")
			sb.WriteString(v.S)
		}
		sb.WriteString("\x00")
	}
	return sb.String()
}

func keyOf(v Value) string { return rowKey([]Value{v}) }

func selHasAgg(sel *Select) bool {
	for _, c := range sel.Cols {
		if hasAggregate(c.Expr) {
			return true
		}
	}
	if hasAggregate(sel.Having) {
		return true
	}
	for _, o := range sel.Order {
		if hasAggregate(o.Expr) {
			return true
		}
	}
	return false
}

func sortResult(rows [][]Value, colList []SelectCol, colExprs []Expr, terms []OrderTerm, db *DB, ctes map[string]*Table, srcRows []*RowCtx) error {
	// compute sort keys
	type item struct {
		row  []Value
		keys []Value
	}
	items := make([]item, len(rows))
	// map from expression text to result index for alias resolution
	aliasIdx := map[string]int{}
	for i, c := range colList {
		if c.Alias != "" {
			aliasIdx[strings.ToLower(c.Alias)] = i
		}
	}
	for i, r := range rows {
		items[i].row = r
		items[i].keys = make([]Value, len(terms))
	}
	for ti, t := range terms {
		// integer literal → result column
		if lv, ok := t.Expr.(*LitVal); ok && lv.Val.T == VInt {
			n := int(lv.Val.I) - 1
			if n >= 0 && n < len(rows) && len(rows) > 0 && n < len(rows[0]) {
				for i := range rows {
					items[i].keys[ti] = rows[i][n]
				}
				continue
			}
		}
		if cr, ok := t.Expr.(*ColRef); ok && cr.Table == "" {
			if n, ok2 := aliasIdx[strings.ToLower(cr.Name)]; ok2 {
				for i := range rows {
					if n < len(rows[i]) {
						items[i].keys[ti] = rows[i][n]
					}
					continue
				}
				continue
			}
			// also match output column name
			for n, c := range colList {
				if strings.EqualFold(colNameOf(c, colExprs[n]), cr.Name) {
					for i := range rows {
						if n < len(rows[i]) {
							items[i].keys[ti] = rows[i][n]
						}
					}
					goto matched
				}
			}
			// fall back: evaluate against source rows
			for i := range rows {
				var rc *RowCtx
				if i < len(srcRows) {
					rc = srcRows[i]
				} else {
					rc = &RowCtx{}
				}
				env := &Env{DB: db, Row: rc, CTEs: ctes}
				v := env.Eval(t.Expr)
				items[i].keys[ti] = v
				if env.Err != nil {
					return env.Err
				}
			}
			continue
		matched:
			continue
		}
		// general expression: evaluate against source rows
		for i := range rows {
			var rc *RowCtx
			if i < len(srcRows) {
				rc = srcRows[i]
			} else {
				rc = &RowCtx{}
			}
			env := &Env{DB: db, Row: rc, CTEs: ctes}
			v := env.Eval(t.Expr)
			items[i].keys[ti] = v
			if env.Err != nil {
				return env.Err
			}
		}
	}
	// stable sort using all keys
	idx := make([]int, len(items))
	for i := range idx {
		idx[i] = i
	}
	var less func(a, b int) bool
	less = func(a, b int) bool {
		for ti := range terms {
			va := items[a].keys[ti]
			vb := items[b].keys[ti]
			if va.T == VNull && vb.T == VNull {
				continue
			}
			if va.T == VNull {
				if terms[ti].Nulls == 1 {
					return true
				}
				if terms[ti].Nulls == 2 {
					return false
				}
				if terms[ti].Desc {
					return true
				}
				return true
			}
			if vb.T == VNull {
				if terms[ti].Nulls == 1 {
					return false
				}
				if terms[ti].Nulls == 2 {
					return true
				}
				if terms[ti].Desc {
					return false
				}
				return false
			}
			c := cmpAff(va, 0, vb, 0)
			if c == 0 {
				continue
			}
			if terms[ti].Desc {
				return c > 0
			}
			return c < 0
		}
		return false
	}
	sortStable(idx, less)
	out := make([][]Value, len(items))
	for i, n := range idx {
		out[i] = items[n].row
	}
	copy(rows, out)
	return nil
}

func sortStable(idx []int, less func(a, b int) bool) {
	// insertion sort is fine for small data; use stable merge sort for large
	n := len(idx)
	if n < 32 {
		for i := 1; i < n; i++ {
			for j := i; j > 0 && less(idx[j], idx[j-1]); j-- {
				idx[j], idx[j-1] = idx[j-1], idx[j]
			}
		}
		return
	}
	mid := n / 2
	left := make([]int, mid)
	right := make([]int, n-mid)
	copy(left, idx[:mid])
	copy(right, idx[mid:])
	sortStable(left, less)
	sortStable(right, less)
	i, j, k := 0, 0, 0
	for i < len(left) && j < len(right) {
		if less(left[i], right[j]) {
			idx[k] = left[i]
			i++
		} else {
			idx[k] = right[j]
			j++
		}
		k++
	}
	for i < len(left) {
		idx[k] = left[i]
		i++
		k++
	}
	for j < len(right) {
		idx[k] = right[j]
		j++
		k++
	}
}

func colNameOf(c SelectCol, e Expr) string {
	if c.Alias != "" {
		return c.Alias
	}
	if cr, ok := e.(*ColRef); ok {
		return cr.Name
	}
	return exprText(e)
}

// exprText returns the source text of an expression (best effort).
func exprText(e Expr) string {
	switch node := e.(type) {
	case nil:
		return ""
	case *LitVal:
		switch node.Val.T {
		case VNull:
			return "NULL"
		case VInt:
			return fmt.Sprintf("%d", node.Val.I)
		case VReal:
			return fmtFloat(node.Val.F)
		default:
			return "'" + node.Val.S + "'"
		}
	case *ColRef:
		if node.Table != "" {
			return node.Table + "." + node.Name
		}
		return node.Name
	case *StarRef:
		return "*"
	case *BinOp:
		return exprText(node.L) + " " + node.Op + " " + exprText(node.R)
	case *UnaryOp:
		return node.Op + exprText(node.E)
	case *FuncExpr:
		s := node.Name + "("
		if node.Star {
			s += "*"
		} else {
			for i, a := range node.Args {
				if i > 0 {
					s += ","
				}
				s += exprText(a)
			}
		}
		return s + ")"
	case *CaseExpr:
		s := "CASE"
		if node.Base != nil {
			s += " " + exprText(node.Base)
		}
		for _, w := range node.Whens {
			s += " WHEN " + exprText(w.When) + " THEN " + exprText(w.Then)
		}
		if node.Else != nil {
			s += " ELSE " + exprText(node.Else)
		}
		return s + " END"
	case *InExpr:
		s := exprText(node.E) + " IN ("
		for i, x := range node.List {
			if i > 0 {
				s += ","
			}
			s += exprText(x)
		}
		return s + ")"
	case *BetweenExpr:
		return exprText(node.E) + " BETWEEN " + exprText(node.Lo) + " AND " + exprText(node.Hi)
	case *LikeExpr:
		return exprText(node.E) + " LIKE " + exprText(node.Pat)
	case *IsExpr:
		return exprText(node.E) + " IS " + exprText(node.Val)
	case *NullExpr:
		if node.Not {
			return exprText(node.E) + " IS NOT NULL"
		}
		return exprText(node.E) + " IS NULL"
	case *SubqExpr:
		return "(select)"
	case *ExistsExpr:
		return "EXISTS(...)"
	case *CastExpr:
		return "CAST(" + exprText(node.E) + " AS " + node.Type + ")"
	case *CollateExpr:
		return exprText(node.E) + " COLLATE " + node.Name
	case *ParamExpr:
		return node.Text
	}
	return "?"
}
