		return IntValue(0), 0
	case "like":
		v, p := arg(args, 0), arg(args, 1)
		if len(args) > 2 {
			esc := arg(args, 2)
			if v.T == VNull || p.T == VNull || esc.T == VNull {
				return NullValue(), 0
			}
			if likeMatch(p.ToText(), v.ToText(), esc.ToText()) {
				return IntValue(1), 0
			}
			return IntValue(0), 0
		}
		if v.T == VNull || p.T == VNull {
			return NullValue(), 0
		}
		if likeMatch(p.ToText(), v.ToText(), "") {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case "regexp":
		p, v := arg(args, 0), arg(args, 1)
		if p.T == VNull || v.T == VNull {
			return NullValue(), 0
		}
		if regexpMatch(p.ToText(), v.ToText()) {
			return IntValue(1), 0
		}
		return IntValue(0), 0
	case "date", "time", "datetime", "julianday", "unixepoch", "strftime":
		return dateFunc(name, args)
	case "json":
		v := arg(args, 0)
		return TextValue(jsonCompact(v)), 0
	case "json_quote":
		v := arg(args, 0)
		return TextValue(jsonQuote(v)), 0
	case "json_extract":
		v := arg(args, 0)
		p := arg(args, 1)
		if v.T == VNull || p.T == VNull {
			return NullValue(), 0
		}
		return jsonExtract(v.ToText(), p.ToText()), 0
	case "json_type":
		v := arg(args, 0)
		if v.T == VNull {
			return NullValue(), 0
		}
		return TextValue(jsonType(v.ToText())), 0
	case "sqlite_version":
		return TextValue("3.51.1"), 0
	case "sqlite_source_id":
		return TextValue("2025-01-01 00:00:00"), 0
	case "changes":
		return IntValue(0), 0
	case "total_changes":
		return IntValue(0), 0
	case "last_insert_rowid":
		return IntValue(0), 0
	case "randomblob":
		return BlobValue(""), 0
	case "hex2":
		return NullValue(), 0
	case "concat":
		var sb strings.Builder
		for _, a := range args {
			if a.T == VNull {
				continue
			}
			sb.WriteString(a.ToText())
		}
		return TextValue(sb.String()), 0
	case "concat_ws":
		sep := arg(args, 0)
		if sep.T == VNull {
			return NullValue(), 0
