func mathFn1(args []Value, f func(float64) float64) (Value, int) {
	v := arg(args, 0)
	if v.T == VNull {
		return NullValue(), 0
	}
	return RealValue(f(v.ToReal())), 0
}

func mathFn2(args []Value, f func(a, b float64) float64) (Value, int) {
	a, b := arg(args, 0), arg(args, 1)
	if a.T == VNull || b.T == VNull {
		return NullValue(), 0
	}
	return RealValue(f(a.ToReal(), b.ToReal())), 0
}

func trimFn(args []Value, left, right bool) (Value, int) {
	v := arg(args, 0)
	if v.T == VNull {
		return NullValue(), 0
	}
	s := v.ToText()
	if v.T == VBlob {
		// trim bytes
		cs := " "
		if len(args) > 1 {
			c := arg(args, 1)
			if c.T == VNull {
				return BlobValue(s), 0
			}
			cs = c.S
		}
		s = trimStr(s, cs, left, right)
		return BlobValue(s), 0
	}
	cs := " "
	if len(args) > 1 {
		c := arg(args, 1)
		if c.T == VNull {
			return TextValue(s), 0
		}
		cs = c.ToText()
	}
	s = trimStr(s, cs, left, right)
	return TextValue(s), 0
}

func trimStr(s, cut string, left, right bool) string {
	if cut == "" {
		return s
	}
	if left {
		for strings.HasPrefix(s, cut) {
			s = s[len(cut):]
		}
	}
	if right {
		for strings.HasSuffix(s, cut) {
			s = s[:len(s)-len(cut)]
		}
	}
	return s
}

func hexEncode(s string) string {
	const hexdigits = "0123456789abcdef"
	out := make([]byte, 0, len(s)*2)
	for i := 0; i < len(s); i++ {
		out = append(out, hexdigits[s[i]>>4], hexdigits[s[i]&0xf])
	}
	return string(out)
}

func utf8Len(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

func utf8DecodeRune(s string) (rune3, int) {
	return decodeRune(s)
}

type rune3 = rune

func sqlQuote(v Value) string {
	switch v.T {
	case VNull:
		return "NULL"
	case VInt:
		return strconv.FormatInt(v.I, 10)
	case VReal:
		return fmtFloat(v.F)
	case VBlob:
		return "X'" + strings.ToUpper(hexEncode(v.S)) + "'"
	default:
		return "'" + strings.ReplaceAll(v.S, "'", "''") + "'"
	}
}

// Aggregates
func (e *Env) evalAgg(node *FuncExpr) (Value, int) {
	if e.Groups == nil {
		// aggregate outside a group context: treat the single row as a group
		rows := []*RowCtx{}
		if e.Row != nil {
			rows = []*RowCtx{e.Row}
		}
		return e.computeAgg(node, rows)
	}
	return e.computeAgg(node, e.Groups.Rows)
}

func (e *Env) computeAgg(node *FuncExpr, rows []*RowCtx) (Value, int) {
	switch node.Name {
	case "count":
		if node.Star {
			return IntValue(int64(len(rows))), 0
		}
		n := int64(0)
		for _, rc := range rows {
			env := &Env{DB: e.DB, Row: rc, CTEs: e.CTEs}
			var v Value
			if len(node.Args) > 0 {
				v = env.Eval(node.Args[0])
			}
			if env.Err != nil {
				e.setError(env.Err)
				return NullValue(), 0
			}
			if v.T != VNull {
				n++
			}
		}
		return IntValue(n), 0
	case "sum", "total":
		var isum int64
		var fsum float64
		isInt := true
		has := false
		for _, rc := range rows {
			env := &Env{DB: e.DB, Row: rc, CTEs: e.CTEs}
			var v Value
			if len(node.Args) > 0 {
				v = env.Eval(node.Args[0])
			}
			if env.Err != nil {
				e.setError(env.Err)
				return NullValue(), 0
			}
			if v.T == VNull {
				continue
			}
			has = true
			nv := v.ToNum()
			if nv.T == VNull {
				continue
			}
			if nv.T == VReal {
				isInt = false
				fsum += nv.F
			} else {
				isum += nv.I
				fsum += float64(nv.I)
			}
		}
		if node.Name == "total" {
			return RealValue(fsum), 0
		}
		if !has {
			return NullValue(), 0
		}
		if isInt {
			return IntValue(isum), 0
		}
		return RealValue(fsum), 0
	case "avg":
		var fsum float64
		n := 0
		for _, rc := range rows {
			env := &Env{DB: e.DB, Row: rc, CTEs: e.CTEs}
			var v Value
			if len(node.Args) > 0 {
				v = env.Eval(node.Args[0])
			}
			if env.Err != nil {
				e.setError(env.Err)
				return NullValue(), 0
			}
			if v.T == VNull {
				continue
			}
			fsum += v.ToReal()
			n++
		}
		if n == 0 {
			return NullValue(), 0
		}
		return RealValue(fsum / float64(n)), 0
	case "min", "max":
		var best Value
		has := false
		for _, rc := range rows {
			env := &Env{DB: e.DB, Row: rc, CTEs: e.CTEs}
			var v Value
			if len(node.Args) > 0 {
				v = env.Eval(node.Args[0])
			}
			if env.Err != nil {
				e.setError(env.Err)
				return NullValue(), 0
			}
			if v.T == VNull {
				continue
			}
			if !has {
				best = v
				has = true
			} else {
				c := cmpAff(v, 0, best, 0)
				if (node.Name == "min" && c < 0) || (node.Name == "max" && c > 0) {
					best = v
				}
			}
		}
		if !has {
			return NullValue(), 0
		}
		return best, 0
	case "group_concat", "string_agg":
		sep := ","
		var sepArg Expr
		if len(node.Args) > 1 {
			sepArg = node.Args[1]
		}
		var parts []string
		for _, rc := range rows {
			env := &Env{DB: e.DB, Row: rc, CTEs: e.CTEs}
			var v Value
			if len(node.Args) > 0 {
				v = env.Eval(node.Args[0])
			}
			var sv string
			if sepArg != nil {
				x := env.Eval(sepArg)
				sv = x.ToText()
			}
			if env.Err != nil {
				e.setError(env.Err)
				return NullValue(), 0
			}
			if v.T == VNull {
				continue
			}
			parts = append(parts, v.ToText())
			if sepArg != nil {
				sep = sv
			}
		}
		if len(parts) == 0 {
			return NullValue(), 0
		}
		return TextValue(strings.Join(parts, sep)), 0
	}
	return NullValue(), 0
}

// dateFunc implements SQLite date/time functions.
func dateFunc(name string, args []Value) (Value, int) {
	switch name {
	case "strftime":
		if len(args) < 1 {
			return NullValue(), 0
		}
		fmtArg := arg(args, 0)
		var t time.Time
		var ok bool
		if len(args) > 1 {
			t, ok = parseDateArg(arg(args, 1))
		} else {
			t, ok = time.Now(), true
		}
		if !ok || fmtArg.T == VNull {
			return NullValue(), 0
		}
		return TextValue(sqlStrftime(fmtArg.ToText(), t)), 0
	}
	var v Value
	if len(args) > 0 {
		v = arg(args, 0)
	} else {
		v = TextValue("now")
	}
	if v.T == VNull {
		return NullValue(), 0
	}
	t, ok := parseDateArg(v)
	if !ok {
		return NullValue(), 0
	}
	switch name {
	case "date":
		return TextValue(t.Format("2006-01-02")), 0
	case "time":
		return TextValue(t.Format("15:04:05")), 0
	case "datetime":
		return TextValue(t.Format("2006-01-02 15:04:05")), 0
	case "unixepoch":
		return IntValue(t.Unix()), 0
	case "julianday":
		return RealValue(julianDay(t)), 0
	}
	return NullValue(), 0
}

func parseDateArg(v Value) (time.Time, bool) {
	s := strings.TrimSpace(v.ToText())
	if s == "" {
		return time.Time{}, false
	}
	if s == "now" {
		return time.Now().UTC(), true
	}
	layouts := []string{
		"2006-01-02 15:04:05.000-07:00",
		"2006-01-02 15:04:05-07:00",
		"2006-01-02T15:04:05.000-07:00",
		"2006-01-02T15:04:05-07:00",
		"2006-01-02 15:04:05.000",
		"2006-01-02 15:04:05",
		"2006-01-02T15:04:05.000",
		"2006-01-02T15:04:05",
		"2006-01-02T15:04",
		"2006-01-02 15:04",
		"2006-01-02",
		"15:04:05",
		"15:04",
	}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t.UTC(), true
		}
	}
	// numeric: unix epoch or julian day
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		if f > 10000000000 {
			return time.Unix(int64(f), 0).UTC(), true
		}
		return julianToTime(f), true
	}
	return time.Time{}, false
}

func julianToTime(j float64) time.Time {
	// JDT unix: 2440587.5 = 1970-01-01
	sec := int64((j - 2440587.5) * 86400)
	return time.Unix(sec, 0).UTC()
}

func julianDay(t time.Time) float64 {
	return float64(t.Unix())/86400.0 + 2440587.5
}

var strftimeMap = []struct{ c byte; gofmt string }{
	{'Y', "2006"}, {'m', "01"}, {'d', "02"}, {'H', "15"}, {'M', "04"}, {'S', "05"},
	{'j', "__yday__"}, {'s', "__unix__"}, {'f', "__frac__"}, {'w', "__wday__"},
	{'W', "__week__"}, {'F', "2006-01-02"}, {'T', "15:04:05"},
}

func sqlStrftime(format string, t time.Time) string {
	var sb strings.Builder
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' {
			sb.WriteByte(c)
			continue
		}
		i++
		if i >= len(format) {
			sb.WriteByte('%')
			break
		}
		c = format[i]
		switch c {
		case 'Y':
			sb.WriteString(t.Format("2006"))
		case 'm':
			sb.WriteString(t.Format("01"))
		case 'd':
			sb.WriteString(t.Format("02"))
		case 'H':
			sb.WriteString(t.Format("15"))
		case 'M':
			sb.WriteString(t.Format("04"))
		case 'S':
			sb.WriteString(t.Format("05"))
		case 'j':
			sb.WriteString(fmt.Sprintf("%03d", t.YearDay()))
		case 's':
			sb.WriteString(fmt.Sprintf("%d", t.Unix()))
		case 'w':
			sb.WriteString(fmt.Sprintf("%d", int(t.Weekday())))
		case 'F':
			sb.WriteString(t.Format("2006-01-02"))
		case 'T':
			sb.WriteString(t.Format("15:04:05"))
		case '%':
			sb.WriteByte('%')
		default:
			sb.WriteByte('%')
			sb.WriteByte(c)
		}
	}
	return sb.String()
}
