package main

import (
	"strconv"
	"strings"
)

// jsonCompact produces a compact JSON representation of a value.
func jsonCompact(v Value) string {
	if v.T == VNull {
		return "null"
	}
	if v.T == VText || v.T == VBlob {
		s := strings.TrimSpace(v.S)
		switch s {
		case "":
			return `""`
		}
		return s
	}
	return `"` + escapeJSON(v.ToText()) + `"`
}

func jsonQuote(v Value) string {
	switch v.T {
	case VNull:
		return "null"
	case VInt:
		return strconv.FormatInt(v.I, 10)
	case VReal:
		return fmtFloat(v.F)
	case VBlob:
		return `"` + escapeJSON(v.S) + `"`
	default:
		return `"` + escapeJSON(v.S) + `"`
	}
}

func escapeJSON(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		case '\f':
			sb.WriteString(`\f`)
		case '\b':
			sb.WriteString(`\b`)
		default:
			if r < 0x20 {
				sb.WriteString(`\u`)
				h := strconv.FormatInt(int64(r), 16)
				for len(h) < 4 {
					h = "0" + h
				}
				sb.WriteString(h)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	return sb.String()
