// jsonType returns the JSON type of a text value.
func jsonType(s string) string {
	t := strings.TrimSpace(s)
	switch t {
	case "":
		return "object"
	}
	if t[0] == '[' {
		return "array"
	}
	if t[0] == '{' {
		return "object"
	}
	switch t {
	case "null":
		return "null"
	case "true", "false":
		return "boolean"
	}
