// jsonGet navigates a JSON text using a path like $.a.b or $[0].
func jsonGet(s, path string) (Value, bool) {
	p := strings.TrimSpace(path)
	if p == "" || p == "$" {
		return TextValue(s), true
	}
	p = strings.TrimPrefix(p, "$")
	var cur string = s
	isObj := false
	isArr := false
	if strings.HasPrefix(strings.TrimSpace(s), "{") {
		isObj = true
	} else if strings.HasPrefix(strings.TrimSpace(s), "[") {
		isArr = true
	}
