				return NullValue(), false
			}
			nv, ok := jsonIndex(cur, idx)
			if !ok {
				return NullValue(), false
			}
			cur = nv
			if strings.HasPrefix(strings.TrimSpace(cur), "{") {
				isObj, isArr = true, false
			} else if strings.HasPrefix(strings.TrimSpace(cur), "[") {
				isObj, isArr = false, true
			} else {
				isObj, isArr = false, false
			}
			continue
		}
		return NullValue(), false
	}
