}

func jsonScalar(s string) Value {
	t := strings.TrimSpace(s)
	switch t {
	case "null":
		return NullValue()
	case "true":
		return IntValue(1)
	case "false":
		return IntValue(0)
	}
	if len(t) > 0 && (t[0] == '{' || t[0] == '[' || t[0] == '"') {
		return TextValue(t)
	}
