		return IntValue(i)
	}
	if f, err := strconv.ParseFloat(t, 64); err == nil {
		return RealValue(f)
	}
	return TextValue(t)
}

// jsonSplit splits a JSON object or array into element strings.
func jsonSplit(s string) (elems []string, keys []string, ok bool) {
	t := strings.TrimSpace(s)
	if t == "" {
		return nil, nil, false
	}
	open := t[0]
	var closeCh byte
	if open == '{' {
		closeCh = '}'
	} else if open == '[' {
		closeCh = ']'
	} else {
		return nil, nil, false
	}
	depth := 0
	inStr := false
	esc := false
	start := 1
	var elems2 []string
	var keys2 []string
	var curKey string
	for i := 1; i < len(t); i++ {
		c := t[i]
		if inStr {
			if esc {
				esc = false
				continue
			}
			if c == '\\' {
				esc = true
				continue
			}
			if c == '"' {
				inStr = false
			}
			continue
		}
		switch c {
		case '"':
			inStr = true
		case '{', '[':
			depth++
		case '}', ']':
			depth--
		case ':':
			if depth == 0 && open == '{' {
				curKey = strings.TrimSpace(t[start:i])
				curKey = strings.Trim(curKey, `"`)
				start = i + 1
			}
		case ',':
			if depth == 0 {
				elem := strings.TrimSpace(t[start:i])
				elems2 = append(elems2, elem)
				keys2 = append(keys2, curKey)
				curKey = ""
				start = i + 1
			}
		}
	}
	if depth != 0 {
		return nil, nil, false
	}
	last := strings.TrimSpace(t[start : len(t)-1])
	if last != "" || len(t) > 2 {
		elems2 = append(elems2, last)
		keys2 = append(keys2, curKey)
	}
	return elems2, keys2, true
}

func jsonField(s, key string) (string, bool) {
	elems, keys, ok := jsonSplit(s)
	if !ok {
		return "", false
	}
	for i, k := range keys {
		if k == key {
			return elems[i], true
		}
	}
	return "", false
}

func jsonIndex(s string, idx int) (string, bool) {
	elems, _, ok := jsonSplit(s)
	if !ok {
		return "", false
	}
	if idx < 0 {
		idx += len(elems)
	}
	if idx < 0 || idx >= len(elems) {
		return "", false
	}
	return elems[idx], true
}
