		for i < len(format) {
			switch format[i] {
			case '-':
				flagMinus = true
			case '+':
				flagPlus = true
			case ' ':
				flagSpace = true
			case '0':
				flagZero = true
			case '#':
				flagSharp = true
			default:
				goto flagsDone
			}
			i++
		}
	flagsDone:
		width := 0
		for i < len(format) && format[i] >= '0' && format[i] <= '9' {
			width = width*10 + int(format[i]-'0')
			i++
		}
		prec := -1
		if i < len(format) && format[i] == '.' {
			i++
			prec = 0
			for i < len(format) && format[i] >= '0' && format[i] <= '9' {
				prec = prec*10 + int(format[i]-'0')
				i++
			}
		}
		if i >= len(format) {
			break
		}
		conv := format[i]
		v, ok := nextArg()
		if !ok {
			v = NullValue()
		}
		switch conv {
		case 'd', 'i':
			n := v.ToInt()
			s := strconv.FormatInt(n, 10)
			if flagPlus && n >= 0 {
				s = "+" + s
			} else if flagSpace && n >= 0 {
				s = " " + s
			}
			if width > len(s) {
				if flagMinus {
					s += strings.Repeat(" ", width-len(s))
				} else if flagZero {
					if strings.HasPrefix(s, "-") {
						s = "-" + strings.Repeat("0", width-len(s)) + s[1:]
					} else if strings.HasPrefix(s, "+") {
						s = "+" + strings.Repeat("0", width-len(s)) + s[1:]
					} else {
						s = strings.Repeat("0", width-len(s)) + s
					}
				} else {
					s = strings.Repeat(" ", width-len(s)) + s
				}
			}
			out.WriteString(s)
		case 'u':
			out.WriteString(padNum(strconv.FormatUint(uint64(v.ToInt()), 10), width, flagMinus, flagZero))
		case 'f', 'e', 'E', 'g', 'G':
			f := v.ToReal()
			var s string
			switch conv {
			case 'f':
				if prec < 0 {
					prec = 6
				}
				s = fmt.Sprintf("%.*f", prec, f)
			case 'e':
				if prec < 0 {
					prec = 6
				}
				s = fmt.Sprintf("%.*e", prec, f)
			case 'E':
				if prec < 0 {
					prec = 6
				}
				s = fmt.Sprintf("%.*E", prec, f)
			case 'g':
				if prec < 0 {
					prec = 15
				}
				s = strconv.FormatFloat(f, 'g', prec, 64)
			case 'G':
				if prec < 0 {
					prec = 15
				}
				s = strings.ToUpper(strconv.FormatFloat(f, 'g', prec, 64))
			}
			out.WriteString(padNum(s, width, flagMinus, flagZero))
		case 's':
			s := v.ToText()
			if prec >= 0 && len(s) > prec {
				s = s[:prec]
			}
			if width > len(s) {
				if flagMinus {
					s += strings.Repeat(" ", width-len(s))
				} else {
					s = strings.Repeat(" ", width-len(s)) + s
				}
			}
			out.WriteString(s)
		case 'q':
			s := "'" + strings.ReplaceAll(v.ToText(), "'", "''") + "'"
			out.WriteString(s)
		case 'Q':
			out.WriteString(sqlQuote(v))
		case 'w':
			out.WriteString(v.ToText())
		case 'c':
			out.WriteString(string(rune(v.ToInt())))
		case 'x':
			out.WriteString(padNum(strings.ToLower(hexFormat(v.ToInt())), width, flagMinus, flagZero))
		case 'X':
			out.WriteString(padNum(strings.ToUpper(hexFormat(v.ToInt())), width, flagMinus, flagZero))
		case 'o':
			out.WriteString(padNum(strconv.FormatInt(v.ToInt(), 8), width, flagMinus, flagZero))
		default:
			out.WriteByte('%')
			out.WriteByte(conv)
		}
	}
	return TextValue(out.String()), 0
}

func hexFormat(i int64) string {
	return strconv.FormatInt(i, 16)
}

func padNum(s string, width int, minus, zero bool) string {
	if width <= len(s) {
		return s
	}
	if minus {
		return s + strings.Repeat(" ", width-len(s))
	}
	if zero {
		if strings.HasPrefix(s, "-") {
			return "-" + strings.Repeat("0", width-len(s)) + s[1:]
		}
		return strings.Repeat("0", width-len(s)) + s
	}
	return strings.Repeat(" ", width-len(s)) + s
}
