package main

import (
	"errors"
	"strings"
)

const (
	jkNull = iota
	jkBool
	jkNumber
	jkString
	jkObject
	jkArray
)

type jsonKV struct {
	key string
	val *jsonValue
}

type jsonValue struct {
	kind  int
	str   string // string value or raw text
	num   string
	bool  bool
	pairs []jsonKV
	items []*jsonValue
	raw   string
}

func (v *jsonValue) scalarOrRaw() string {
	switch v.kind {
	case jkString:
		return v.str
	case jkNumber:
		return v.num
	case jkBool:
		if v.bool {
			return "true"
		}
		return "false"
	case jkNull:
		return ""
	default:
		return v.raw
	}
}

type jsonObj struct {
	keys   []string
	values map[string]string
	hasNull map[string]bool
}

// jsonDecoder reads successive JSON values from a string.
type jsonDecoder struct {
	s string
	i int
}

var errJSONEnd = errors.New("end")

func (d *jsonDecoder) ws() {
	for d.i < len(d.s) {
		c := d.s[d.i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			d.i++
			continue
		}
		break
	}
}

func (d *jsonDecoder) next() (*jsonValue, error) {
	d.ws()
	if d.i >= len(d.s) {
		return nil, nil
	}
	start := d.i
	v, err := d.parseValue()
	if err != nil {
		return nil, err
	}
	v.raw = strings.TrimSpace(d.s[start:d.i])
	return v, nil
}

func (d *jsonDecoder) parseValue() (*jsonValue, error) {
	d.ws()
	if d.i >= len(d.s) {
		return nil, nil
	}
	switch d.s[d.i] {
	case '{':
		return d.parseObject()
	case '[':
		return d.parseArray()
	case '"':
		s, err := d.parseString()
		if err != nil {
			return nil, err
		}
		return &jsonValue{kind: jkString, str: s}, nil
	case 't':
		if strings.HasPrefix(d.s[d.i:], "true") {
			d.i += 4
			return &jsonValue{kind: jkBool, bool: true}, nil
		}
		return nil, errSyntax
	case 'f':
		if strings.HasPrefix(d.s[d.i:], "false") {
			d.i += 5
			return &jsonValue{kind: jkBool, bool: false}, nil
		}
		return nil, errSyntax
	case 'n':
		if strings.HasPrefix(d.s[d.i:], "null") {
			d.i += 4
			return &jsonValue{kind: jkNull}, nil
		}
		return nil, errSyntax
	default:
		start := d.i
		for d.i < len(d.s) {
			c := d.s[d.i]
			if (c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
				d.i++
				continue
			}
			break
		}
		if d.i == start {
			return nil, &jsonSyntaxError{msg: "invalid character '" + string(rune(d.s[d.i])) + "' looking for beginning of value"}
		}
		return &jsonValue{kind: jkNumber, num: d.s[start:d.i]}, nil
	}
}

type jsonSyntaxError struct{ msg string }

func (e *jsonSyntaxError) Error() string { return e.msg }

var errSyntax = &jsonSyntaxError{msg: "invalid character"}

func (d *jsonDecoder) parseString() (string, error) {
	if d.s[d.i] != '"' {
		return "", &jsonSyntaxError{msg: "invalid character '" + string(rune(d.s[d.i])) + "' looking for beginning of value"}
	}
	d.i++
	var sb strings.Builder
	for d.i < len(d.s) {
		c := d.s[d.i]
		if c == '"' {
			d.i++
			return sb.String(), nil
		}
		if c == '\\' {
			d.i++
			if d.i >= len(d.s) {
				return "", errors.New("unexpected end of JSON input")
			}
			e := d.s[d.i]
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'u':
				if d.i+4 < len(d.s) {
					code := 0
					ok := true
					for k := 1; k <= 4; k++ {
						h := hexVal(d.s[d.i+k])
						if h < 0 {
							ok = false
							break
						}
						code = code*16 + h
					}
					if ok {
						sb.WriteRune(rune(int64(code)))
						d.i += 5
						continue
					}
				}
				sb.WriteByte('u')
			default:
				sb.WriteByte(e)
			}
			d.i++
			continue
		}
		sb.WriteByte(c)
		d.i++
	}
	return "", errors.New("unexpected end of JSON input")
}

func (d *jsonDecoder) parseObject() (*jsonValue, error) {
	d.i++ // {
	v := &jsonValue{kind: jkObject}
	for {
		d.ws()
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		if d.s[d.i] == '}' {
			d.i++
			return v, nil
		}
		key, err := d.parseString()
		if err != nil {
			return nil, err
		}
		d.ws()
		if d.i >= len(d.s) || d.s[d.i] != ':' {
			return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after object key"}
		}
		d.i++
		val, err := d.parseValue()
		if err != nil {
			return nil, err
		}
		v.pairs = append(v.pairs, jsonKV{key: key, val: val})
		d.ws()
		if d.i < len(d.s) && d.s[d.i] == ',' {
			d.i++
			continue
		}
		if d.i < len(d.s) && d.s[d.i] == '}' {
			d.i++
			return v, nil
		}
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after object key:value pair"}
	}
}

func (d *jsonDecoder) parseArray() (*jsonValue, error) {
	d.i++ // [
	v := &jsonValue{kind: jkArray}
	for {
		d.ws()
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		if d.s[d.i] == ']' {
			d.i++
			return v, nil
		}
		val, err := d.parseValue()
		if err != nil {
			return nil, err
		}
		v.items = append(v.items, val)
		d.ws()
		if d.i < len(d.s) && d.s[d.i] == ',' {
			d.i++
			continue
		}
		if d.i < len(d.s) && d.s[d.i] == ']' {
			d.i++
			return v, nil
		}
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after array element"}
	}
}

func strAt(s string, i int) string {
	if i >= len(s) {
		return ""
	}
	return string(rune(int64(s[i])))
}
