package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Importer reads rows from a stream.
type Importer struct {
	opt *Opt
	log *Logger
}

func (im *Importer) Import(name string, r io.Reader) (cols []string, rows [][]string, err error) {
	switch im.opt.InFormat {
	case "CSV":
		return im.importCSV(r)
	case "LTSV":
		return im.importLTSV(r)
	case "JSON":
		return im.importJSON(r)
	case "TBLN":
		return im.importTBLN(r)
	case "TEXT":
		return im.importText(r)
	case "WIDTH":
		return im.importWidth(r)
	case "YAML":
		return im.importYAML(r)
	}
	return im.importCSV(r)
}

// importCSV reads CSV rows.
func (im *Importer) importCSV(r io.Reader) (cols []string, rows [][]string, err error) {
	cr := csv.NewReader(r)
	cr.FieldsPerRecord = -1
	cr.LazyQuotes = true
	if im.opt.InDelimiter != 0 {
		cr.Comma = im.opt.InDelimiter
	}
	var all [][]string
	need := im.opt.InPreRead
	if im.opt.InSkip > 0 {
		for i := 0; i < im.opt.InSkip; i++ {
			if _, err = cr.Read(); err != nil {
				if err == io.EOF {
					return nil, nil, fmt.Errorf("no rows")
				}
				return nil, nil, err
			}
		}
	}
	var header []string
	idx := 0
	for {
		rec, e := cr.Read()
		if e == io.EOF {
			break
		}
		if e != nil {
			return nil, nil, e
		}
		if idx == 0 && im.opt.InHeader {
			header = rec
			idx++
			continue
		}
		if len(all) < need {
			all = append(all, rec)
			idx++
			continue
		}
		idx++
		all = append(all, rec)
		if im.opt.InLimitRow > 0 && len(all) >= im.opt.InLimitRow {
			break
		}
	}
	rows = all
	if im.opt.InHeader {
		if header == nil {
			return nil, nil, fmt.Errorf("no rows")
		}
		cols = header
	} else {
		if len(rows) == 0 {
			return nil, nil, fmt.Errorf("no rows")
		}
		n := len(rows[0])
		for i := 0; i < n; i++ {
			cols = append(cols, fmt.Sprintf("c%d", i+1))
		}
	}
	if len(cols) == 0 {
		return nil, nil, fmt.Errorf("invalid names")
	}
	return cols, rows, nil
}

// importLTSV reads labeled tab separated values.
func (im *Importer) importLTSV(r io.Reader) (cols []string, rows [][]string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, nil, err
	}
	lines := strings.Split(string(data), "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	if im.opt.InSkip > 0 {
		if im.opt.InSkip >= len(lines) {
			return nil, nil, fmt.Errorf("no rows")
		}
		lines = lines[im.opt.InSkip:]
	}
	var all [][]string
	var header []string
	colIdx := map[string]int{}
	for _, line := range lines {
		if line == "" {
			continue
		}
		if !strings.Contains(line, ":") {
			return nil, nil, fmt.Errorf("invalid column")
		}
		var keys []string
		var vals []string
		for _, f := range strings.Split(line, "\t") {
			i := strings.Index(f, ":")
			if i < 0 {
				return nil, nil, fmt.Errorf("invalid column")
			}
			k := f[:i]
			v := f[i+1:]
			if _, ok := colIdx[k]; !ok {
				colIdx[k] = len(keys)
				keys = append(keys, k)
			}
			keys, vals = nil, nil
			_ = keys
			_ = vals
			break
		}
		// parse the line properly
		pairs := strings.Split(line, "\t")
		var rec []string
		if len(all) == 0 && !im.opt.InHeader {
			for _, p := range pairs {
				i := strings.Index(p, ":")
				if i < 0 {
					return nil, nil, fmt.Errorf("invalid column")
				}
				colIdx[p[:i]] = len(rec)
				rec = append(rec, p[:i])
			}
			header = rec
			continue
		}
		rec = make([]string, len(header))
		for i := range rec {
			rec[i] = ""
		}
		for _, p := range pairs {
			i := strings.Index(p, ":")
			if i < 0 {
				return nil, nil, fmt.Errorf("invalid column")
			}
			k := p[:i]
			v := p[i+1:]
			if n, ok := colIdx[k]; ok && n < len(rec) {
				rec[n] = v
			}
		}
		all = append(all, rec)
		if im.opt.InLimitRow > 0 && len(all) >= im.opt.InLimitRow {
			break
		}
	}
	if len(all) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	cols = header
	return cols, all, nil
}

// importJSON reads JSON or JSON lines.
func (im *Importer) importJSON(r io.Reader) (cols []string, rows [][]string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, nil, err
	}
	s := string(data)
	dec := &jsonDecoder{s: s}
	var recs []jsonObj
	var first jsonObj
	haveFirst := false
	for {
		v, e := dec.next()
		if e != nil {
			return nil, nil, fmt.Errorf("invalid JSON: %s", e)
		}
		if v == nil {
			break
		}
		for _, rec := range expandJSON(v) {
			if !haveFirst {
				first = rec
				haveFirst = true
			}
			recs = append(recs, rec)
			if im.opt.InLimitRow > 0 && len(recs) >= im.opt.InLimitRow {
				break
			}
		}
		if im.opt.InLimitRow > 0 && len(recs) >= im.opt.InLimitRow {
			break
		}
	}
	if !haveFirst {
		return nil, nil, fmt.Errorf("invalid names")
	}
	cols = first.keys
	if len(cols) == 0 {
		cols = []string{"c1"}
	}
	var out [][]string
	for _, rec := range recs {
		row := make([]string, len(cols))
		for i, c := range cols {
			if v, ok := rec.values[c]; ok {
				row[i] = v
			}
		}
		out = append(out, row)
	}
	rows = out
	if len(rows) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	return cols, rows, nil
}

// jsonObj is a decoded JSON record.
type jsonObj struct {
	keys   []string
	values map[string]string
}

func expandJSON(v *jsonValue) []jsonObj {
	var out []jsonObj
	switch v.kind {
	case jkObject:
		out = append(out, jsonObjFromObject(v))
	case jkArray:
		for _, e := range v.items {
			out = append(out, expandJSON(e)...)
		}
	default:
		out = append(out, jsonObj{keys: []string{"c1"}, values: map[string]string{"c1": v.raw}})
	}
	return out
}

func jsonObjFromObject(v *jsonValue) jsonObj {
	o := jsonObj{values: make(map[string]string)}
	for _, kv := range v.pairs {
		key := kv.key
		o.keys = append(o.keys, key)
		val := kv.val
		if val.kind == jkNull {
			o.values[key] = ""
			o.hasNull[key] = true
			continue
		}
		o.values[key] = val.scalarOrRaw()
	}
	if o.values == nil {
		o.values = make(map[string]string)
	}
	if o.hasNull == nil {
		o.hasNull = make(map[string]bool)
	}
	return o
}

// importTBLN reads tbln format.
func (im *Importer) importTBLN(r io.Reader) (cols []string, rows [][]string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, nil, err
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	var names []string
	var types []string
	var recs [][]string
	bulk := false
	for _, line := range lines {
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, ";") {
			if strings.HasPrefix(line, "; name:") {
				names = tblnSplit(strings.TrimPrefix(line, "; name:"))
			}
			continue
		}
		if !strings.HasPrefix(line, "|") {
			if bulk {
				return nil, nil, fmt.Errorf("bulk read: unsupported line (%s)", line)
			}
			return nil, nil, fmt.Errorf("unsupported line (%s)", line)
		}
		rec := tblnSplit(line)
		recs = append(recs, rec)
		bulk = true
	}
	if len(recs) == 0 {
		return nil, nil, fmt.Errorf("invalid names")
	}
	if len(names) == 0 {
		n := len(recs[0])
		for i := 0; i < n; i++ {
			names = append(names, fmt.Sprintf("c%d", i+1))
		}
	}
	_ = types
	rows = recs
	return names, rows, nil
}

func tblnSplit(line string) []string {
	s := strings.TrimPrefix(line, "|")
	s = strings.TrimSuffix(s, "|")
	return strings.Split(s, "|")
}

// importText reads each line as a single column named "text".
func (im *Importer) importText(r io.Reader) (cols []string, rows [][]string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, nil, err
	}
	s := strings.TrimSuffix(string(data), "\n")
	var out [][]string
	if s != "" {
		for _, line := range strings.Split(s, "\n") {
			out = append(out, []string{line})
			if im.opt.InLimitRow > 0 && len(out) >= im.opt.InLimitRow {
				break
			}
		}
	}
	if len(out) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	return []string{"text"}, out, nil
}

// importWidth reads fixed width text based on column detection.
func (im *Importer) importWidth(r io.Reader) (cols []string, rows [][]string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, nil, err
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	if len(lines) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	if im.opt.InSkip > 0 {
		if im.opt.InSkip >= len(lines) {
			return nil, nil, fmt.Errorf("no rows")
		}
		lines = lines[im.opt.InSkip:]
	}
	if len(lines) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	cuts := widthCuts(lines)
	// build columns from the first line
	var all [][]string
	header := widthSplit(lines[0], cuts)
	if len(header) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	for i, line := range lines {
		if i == 0 {
			continue
		}
		rec := widthSplit(line, cuts)
		all = append(all, rec)
		if im.opt.InLimitRow > 0 && len(all) >= im.opt.InLimitRow {
			break
		}
	}
	if len(all) == 0 {
		return nil, nil, fmt.Errorf("no rows")
	}
	return header, all, nil
}

// widthCuts computes the cut positions from all lines.
func widthCuts(lines []string) []int {
	maxLen := 0
	for _, l := range lines {
		if len(l) > maxLen {
			maxLen = len(l)
		}
	}
	// candidate positions: space in the header and at least one other line
	header := lines[0]
	var cand []int
	for p := 1; p < len(header); p++ {
		if header[p] != ' ' {
			continue
		}
		ok := false
		for _, l := range lines[1:] {
			if p < len(l) && l[p] == ' ' {
				ok = true
				break
			}
		}
		if ok {
			cand = append(cand, p)
		}
	}
	// merge consecutive candidates into runs and cut at run ends
	var cuts []int
	for i := 0; i < len(cand); i++ {
		j := i
		for j+1 < len(cand) && cand[j+1] == cand[j]+1 {
			j++
		}
		cuts = append(cuts, cand[j]+1)
		i = j
	}
	// now adjust: remove cuts that would produce an empty first column
	return cuts
}

func widthSplit(line string, cuts []int) []string {
	var out []string
	prev := 0
	for _, c := range cuts {
		if c > len(line) {
			break
		}
		out = append(out, strings.TrimSpace(line[prev:c]))
		prev = c
	}
	if prev <= len(line) {
		out = append(out, strings.TrimSpace(line[prev:]))
	}
	return out
}

// GuessFormat returns the input format from the file name.
func GuessFormat(name string, guess bool) (string, string) {
	if !guess {
		return "", ""
	}
	ext := ""
	base := name
	for {
		e := extOf(base)
		if e == ".gz" {
			base = base[:len(base)-3]
			continue
		}
		ext = e
		break
	}
	switch ext {
	case ".csv":
		return "CSV", ""
	case ".ltsv":
		return "LTSV", ""
	case ".json", ".jsonl":
		return "JSON", ""
	case ".yaml", ".yml":
		return "YAML", ""
	case ".tbln":
		return "TBLN", ""
	}
	return "CSV", base[:len(base)-len(ext)]
}

func extOf(name string) string {
	i := strings.LastIndexByte(name, '.')
	if i < 0 {
		return ""
	}
	return name[i:]
}

