				if i < 0 {
					return nil, nil, fmt.Errorf("invalid column")
				}
				colIdx[p[:i]] = len(rec)
				rec = append(rec, p[:i])
			}
			header = rec
			continue
		}
		rec = make([]string, len(header))
		for i := range rec {
