	if d.s[d.i] != '"' {
		return "", &jsonSyntaxError{msg: "invalid character '" + string(rune(d.s[d.i])) + "' looking for beginning of value"}
	}
	d.i++
	var sb strings.Builder
	for d.i < len(d.s) {
		c := d.s[d.i]
		if c == '"' {
			d.i++
			return sb.String(), nil
		}
		if c == '\\' {
			d.i++
			if d.i >= len(d.s) {
				return "", errors.New("unexpected end of JSON input")
			}
			e := d.s[d.i]
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'u':
				if d.i+4 < len(d.s) {
					code := 0
					ok := true
					for k := 1; k <= 4; k++ {
						h := hexVal(d.s[d.i+k])
						if h < 0 {
							ok = false
							break
						}
						code = code*16 + h
					}
					if ok {
						sb.WriteRune(rune(int64(code)))
						d.i += 5
						continue
					}
				}
				sb.WriteByte('u')
			default:
				sb.WriteByte(e)
			}
			d.i++
			continue
		}
		sb.WriteByte(c)
		d.i++
	}
	return "", errors.New("unexpected end of JSON input")
}

func (d *jsonDecoder) parseObject() (*jsonValue, error) {
	d.i++ // {
	v := &jsonValue{kind: jkObject}
	for {
		d.ws()
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		if d.s[d.i] == '}' {
			d.i++
			return v, nil
		}
		key, err := d.parseString()
		if err != nil {
			return nil, err
		}
		d.ws()
		if d.i >= len(d.s) || d.s[d.i] != ':' {
			return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after object key"}
		}
		d.i++
		val, err := d.parseValue()
		if err != nil {
			return nil, err
		}
		v.pairs = append(v.pairs, jsonKV{key: key, val: val})
		d.ws()
		if d.i < len(d.s) && d.s[d.i] == ',' {
			d.i++
			continue
		}
		if d.i < len(d.s) && d.s[d.i] == '}' {
			d.i++
			return v, nil
		}
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after object key:value pair"}
	}
}

func (d *jsonDecoder) parseArray() (*jsonValue, error) {
	d.i++ // [
	v := &jsonValue{kind: jkArray}
	for {
		d.ws()
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		if d.s[d.i] == ']' {
			d.i++
			return v, nil
		}
		val, err := d.parseValue()
		if err != nil {
			return nil, err
		}
		v.items = append(v.items, val)
		d.ws()
		if d.i < len(d.s) && d.s[d.i] == ',' {
			d.i++
			continue
		}
		if d.i < len(d.s) && d.s[d.i] == ']' {
			d.i++
			return v, nil
		}
		if d.i >= len(d.s) {
			return nil, errors.New("unexpected end of JSON input")
		}
		return nil, &jsonSyntaxError{msg: "invalid character '" + strAt(d.s, d.i) + "' after array element"}
	}
}

func strAt(s string, i int) string {
	if i >= len(s) {
		return ""
	}
	return string(rune(int64(s[i])))
}
