func (im *Importer) importWidth(r io.Reader) (*Rows, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	if im.opt.InSkip > 0 {
