		}
		lines = lines[im.opt.InSkip:]
	}
	if len(lines) == 0 {
		return nil, fmt.Errorf("no rows")
	}
	cuts := widthCuts(lines)
	var all [][]string
	for i, line := range lines {
		if i == 0 {
			continue
		}
		rec := widthSplit(line, cuts)
		all = append(all, rec)
		if im.limitReached(len(all)) {
			break
		}
	}
	if len(all) == 0 {
		return nil, fmt.Errorf("no rows")
	}
	header := widthSplit(lines[0], cuts)
	return &Rows{Cols: header, Rows: all}, nil
}

// widthCuts computes the cut positions from all lines.
func widthCuts(lines []string) []int {
	header := lines[0]
	var cand []int
	for p := 1; p < len(header); p++ {
		if header[p] != ' ' {
			continue
		}
		ok := false
		for _, l := range lines[1:] {
			if p < len(l) && l[p] == ' ' {
				ok = true
				break
			}
		}
		if ok {
			cand = append(cand, p)
		}
	}
	var cuts []int
	for i := 0; i < len(cand); i++ {
		j := i
		for j+1 < len(cand) && cand[j+1] == cand[j]+1 {
			j++
		}
		cuts = append(cuts, cand[j]+1)
		i = j
	}
	// adjust cuts so that no header column is empty
	adjusted := make([]int, 0, len(cuts))
	prev := 0
	for _, c := range cuts {
		if strings.TrimSpace(header[prev:c]) == "" {
			// merge with the previous column: drop the cut at prev
			continue
		}
		adjusted = append(adjusted, c)
		prev = c
	}
	return adjusted
}

func widthSplit(line string, cuts []int) []string {
	var out []string
	prev := 0
	for _, c := range cuts {
		if c > len(line) {
			break
		}
		out = append(out, strings.TrimSpace(line[prev:c]))
		prev = c
	}
	if prev <= len(line) {
		out = append(out, strings.TrimSpace(line[prev:]))
	}
	return out
}

// GuessFormat returns the input format from the file name.
func GuessFormat(name string, guess bool) (string, string) {
	if !guess {
		return "", ""
	}
	base := name
	for {
		e := extOf(base)
		if e == ".gz" {
			base = base[:len(base)-3]
			continue
		}
		switch e {
		case ".csv":
			return "CSV", ""
		case ".ltsv":
			return "LTSV", ""
		case ".json", ".jsonl":
			return "JSON", ""
		case ".yaml", ".yml":
			return "YAML", ""
		case ".tbln":
			return "TBLN", ""
		}
		return "CSV", base[:len(base)-len(e)]
	}
}

func extOf(name string) string {
	i := strings.LastIndexByte(name, '.')
	if i < 0 {
		return ""
	}
	return name[i:]
}
