		if e == ".gz" {
			base = base[:len(base)-3]
			continue
		}
		switch e {
		case ".csv":
			return "CSV", ""
		case ".ltsv":
			return "LTSV", ""
		case ".json", ".jsonl":
			return "JSON", ""
		case ".yaml", ".yml":
			return "YAML", ""
		case ".tbln":
			return "TBLN", ""
		}
		return "CSV", base[:len(base)-len(e)]
	}
}

func extOf(name string) string {
	i := strings.LastIndexByte(name, '.')
	if i < 0 {
		return ""
	}
	return name[i:]
}
