// jsonObj2 duplicates jsonObj for expansion
func expandJSON(v *jsonValue) []jsonObj {
	var out []jsonObj
	switch v.kind {
	case jkObject:
		out = append(out, jsonObjFromObject(v))
	case jkArray:
		for _, e := range v.items {
			out = append(out, expandJSON(e)...)
		}
	default:
		out = append(out, jsonObj{keys: []string{"c1"}, values: map[string]string{"c1": v.raw}, hasNull: map[string]bool{}})
	}
	return out
}

func jsonObjFromObject(v *jsonValue) jsonObj {
	o := jsonObj{values: make(map[string]string), hasNull: make(map[string]bool)}
	for _, kv := range v.pairs {
		key := kv.key
		o.keys = append(o.keys, key)
		val := kv.val
		if val.kind == jkNull {
			o.values[key] = ""
			o.hasNull[key] = true
			continue
		}
		o.values[key] = val.scalarOrRaw()
	}
	return o
}
