{"command": "cd /workspace/trdsql && cat > export.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

// Exporter writes rows in a specific format.
type Exporter struct {
	opt *Opt
	log *Logger
}

// Table is the data to export.
type OutTable struct {
	Cols []string
	Rows [][]Value
	Nulls []bool // row-level? not used
}

func (e *Exporter) Write(t *OutTable) error {
	switch e.opt.OutFormat {
	case "CSV":
		return e.writeCSV(t)
	case "LTSV":
		return e.writeLTSV(t)
	case "JSON":
		return e.writeJSON(t)
	case "JSONL":
		return e.writeJSONL(t)
	case "MD":
		return e.writeTable(t, true)
	case "AT":
		return e.writeTable(t, false)
	case "RAW":
		return e.writeRaw(t)
	case "TBLN":
		return e.writeTBLN(t)
	case "VF":
		return e.writeVF(t)
	case "YAML":
		return e.writeYAML(t)
	}
	return e.writeCSV(t)
}

// writeCSV writes CSV format.
func (e *Exporter) writeCSV(t *OutTable) error {
	var sb strings.Builder
	if e.opt.OutHeader {
		e.writeCSVRecord(&sb, textsOf(t.Cols))
	}
	for _, row := range t.Rows {
		e.writeCSVRecord(&sb, textsOfRow(row))
	}
	_, err := writeOut(sb.String())
	return err
}

func textsOf(cols []string) []string {
	out := make([]string, len(cols))
	copy(out, cols)
	return out
}

func textsOfRow(row []Value) []string {
	out := make([]string, len(row))
	for i, v := range row {
		out[i] = v.ToText()
	}
	return out
}

func (e *Exporter) csvQuoteNeeded(field string) bool {
	if field == "" {
		return false
	}
	if field == "\\." {
		return true
	}
	if e.opt.OutDelimiter == ' ' {
		field = strings.ReplaceAll(field, " ", "\\.")
	}
	if strings.ContainsRune(field, e.opt.OutDelimiter) || strings.ContainsRune(field, e.opt.OutQuote) {
		return true
	}
	if strings.ContainsAny(field, "\r\n") {
		return true
	}
	if len(field) > 0 {
		r, _ := decodeRune(field)
		if unicodeIsSpace(r) {
			return true
		}
	}
	return false
}

func (e *Exporter) writeCSVRecord(sb *strings.Builder, record []string) {
	for i, field := range record {
		if i > 0 {
			sb.WriteRune(e.opt.OutDelimiter)
		}
		if e.opt.OutAllQuote || e.csvQuoteNeeded(field) {
			sb.WriteRune(e.opt.OutQuote)
			q := string(e.opt.OutQuote)
			sb.WriteString(strings.ReplaceAll(field, q, q+q))
			sb.WriteRune(e.opt.OutQuote)
		} else {
			sb.WriteString(field)
		}
