package main

import (
	"strconv"
	"strings"
)

// writeYAML writes YAML format.
func (e *Exporter) writeYAML(t *OutTable) error {
	var sb strings.Builder
	for _, row := range t.Rows {
		sb.WriteString("- ")
		for j, v := range row {
			if j > 0 {
				sb.WriteString("  ")
			}
			key := t.Cols[j]
			sb.WriteString(yamlKey(key) + ":")
			val := v.ToText()
			s := yamlValue(val, 4)
			if s == "\n" || strings.HasPrefix(s, "\n") {
				sb.WriteString(s)
			} else {
				sb.WriteString(" " + s)
			}
			sb.WriteString("\n")
		}
	}
	_, err := writeOut(sb.String())
	return err
}

func yamlKey(s string) string {
	return yamlScalar(s, true)
}

func yamlValue(s string, indent int) string {
	// try to interpret the value as YAML
	t := strings.TrimSpace(s)
	if t == "" {
		return "null"
	}
	if v, ok := yamlParse(t); ok {
		return v
	}
	return yamlScalar(s, false)
}

// yamlParse parses a simple scalar or nested structure and returns its YAML form.
func yamlParse(s string) (string, bool) {
	if s == "" {
		return "null", true
	}
	switch s {
	case "null", "Null", "NULL", "~":
		return "null", true
	case "true", "True", "TRUE":
		return "true", true
	case "false", "False", "FALSE":
		return "false", true
	case ".inf", "+.inf", ".Inf", ".INF":
		return ".inf", true
	case "-.inf", "-.Inf", "-.INF":
		return "-.inf", true
	case ".nan", ".NaN", ".NAN":
		return ".nan", true
	}
	if i, ok := yamlInt(s); ok {
		return strconv.FormatInt(i, 10), true
	}
	if f, ok := yamlFloat(s); ok {
		return yamlFormatFloat(f), true
	}
	// nested structures
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		elems, _, ok := jsonSplit(s)
		if !ok {
			return "", false
		}
		var parts []string
		for _, e := range elems {
			p, ok2 := yamlParse(e)
			if !ok2 {
				return "", false
			}
			parts = append(parts, yamlScalar(e, true))
			_ = p
		}
		if len(parts) == 0 {
			return "[]", true
		}
		return "\n" + strings.Repeat(" ", 2) + "- " + strings.Join(parts, "\n"+strings.Repeat(" ", 2)+"- "), true
	}
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		elems, keys, ok := jsonSplit(s)
		if !ok {
			return "", false
		}
		var parts []string
		for i, e := range elems {
			k := keys[i]
			v, ok2 := yamlParse(e)
			if !ok2 {
				return "", false
			}
			parts = append(parts, yamlScalar(k, true)+": "+v)
		}
		return "\n" + strings.Repeat(" ", 4) + strings.Join(parts, "\n"+strings.Repeat(" ", 4)), true
	}
	if strings.HasPrefix(s, "- ") {
		// sequence
		lines := strings.Split(s, "\n")
		var parts []string
		for _, l := range lines {
			l = strings.TrimSpace(l)
			l = strings.TrimPrefix(l, "- ")
			p, ok2 := yamlParse(l)
			if !ok2 {
				return "", false
			}
			parts = append(parts, "- "+p)
		}
		return "\n" + strings.Join(parts, "\n"), true
	}
	return "", false
}

func yamlInt(s string) (int64, bool) {
	t := strings.TrimPrefix(strings.TrimPrefix(s, "-"), "+")
	neg := strings.HasPrefix(s, "-")
	if t == "" {
		return 0, false
	}
	var v int64
	var err error
	switch {
	case strings.HasPrefix(t, "0x"), strings.HasPrefix(t, "0X"):
		v, err = strconv.ParseInt(t[2:], 16, 64)
	case strings.HasPrefix(t, "0b"), strings.HasPrefix(t, "0B"):
		v, err = strconv.ParseInt(t[2:], 2, 64)
	case strings.HasPrefix(t, "0o"), strings.HasPrefix(t, "0O"):
		v, err = strconv.ParseInt(t[2:], 8, 64)
	case len(t) > 1 && t[0] == '0':
		v, err = strconv.ParseInt(t[1:], 8, 64)
	default:
		t2 := strings.ReplaceAll(t, "_", "")
		v, err = strconv.ParseInt(t2, 10, 64)
	}
	if err != nil {
		return 0, false
	}
	if neg {
		v = -v
	}
	return v, true
}

func yamlFloat(s string) (float64, bool) {
	t := strings.ReplaceAll(s, "_", "")
	if !strings.ContainsAny(t, ".eE") {
		return 0, false
	}
	if !strings.Contains(t, ".") {
		return 0, false
	}
	f, err := strconv.ParseFloat(t, 64)
	if err != nil {
		return 0, false
	}
	return f, true
}

func yamlFormatFloat(f float64) string {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") && !strings.Contains(s, "inf") && !strings.Contains(s, "nan") {
		s += ".0"
	}
	return s
}

// yamlScalar renders a string as a YAML scalar, quoting when needed.
func yamlScalar(s string, key bool) string {
	if s == "" {
		return `""`
	}
	if !plainOK(s) {
		return `"` + escapeYAML(s) + `"`
	}
	return s
}

func escapeYAML(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\t':
			sb.WriteString(`\t`)
		case '\r':
			sb.WriteString(`\r`)
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

var yamlReserved = map[string]bool{
	"yes": true, "no": true, "on": true, "off": true, "y": true, "n": true,
}

func plainOK(s string) bool {
	if s == "" {
		return false
	}
	if strings.ContainsAny(s, "#\\") {
		return false
	}
	if strings.ContainsAny(s, "\n\r\t") {
		return false
	}
	if yamlReserved[strings.ToLower(s)] {
		return false
	}
	// would be misinterpreted as a number / date / structure
	if i, ok := yamlInt(s); ok {
		_ = i
		return false
	}
	if f, ok := yamlFloat(s); ok {
		_ = f
		return false
	}
	if isDateLike(s) {
		return false
	}
	// leading indicators
	if len(s) > 0 {
		switch s[0] {
		case '*', '&', '!', '|', '>', '%', '@', '`', '#', ',', '[', ']', '{', '}', '\'', '"', '?', ':', '-':
			return false
		}
	}
	if strings.Contains(s, ": ") || strings.HasSuffix(s, ":") {
		return false
	}
	if strings.Contains(s, " #") {
		return false
	}
	if strings.HasPrefix(s, "- ") {
		return false
	}
	return true
}

func isDateLike(s string) bool {
	if len(s) < 8 {
		return false
	}
	// YYYY-MM-DD
	if len(s) == 10 && s[4] == '-' && s[7] == '-' {
		for i, c := range s {
			if i == 4 || i == 7 {
				continue
			}
			if c < '0' || c > '9' {
				return false
			}
		}
		return true
	}
	// YYYY-MM-DD HH:MM:SS
	if len(s) == 19 && s[4] == '-' && s[7] == '-' && s[10] == ' ' && s[13] == ':' && s[16] == ':' {
		return true
	}
	// sexagesimal like 1:30
	if strings.Contains(s, ":") && !strings.Contains(s, " ") {
		parts := strings.Split(s, ":")
		ok := len(parts) >= 2
		for _, p := range parts {
			if p == "" {
				ok = false
				break
			}
			for _, c := range p {
				if c < '0' || c > '9' {
					ok = false
					break
				}
			}
		}
		if ok {
			return true
		}
	}
	return false
}
