const wrapWidth = 30

// wrapText wraps a string into lines of at most max display width.
func wrapText(s string, max int) []string {
	if max <= 0 || StringWidth(s) <= max {
		return []string{s}
	}
	var lines []string
	words := splitWords(s)
	if len(words) == 0 {
		return []string{s}
	}
	cur := ""
	for _, w := range words {
		if cur == "" {
			cur = w
			continue
		}
		if StringWidth(cur)+1+StringWidth(w) <= max {
			cur += " " + w
			continue
		}
		lines = append(lines, cur)
		cur = w
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	if len(lines) == 1 {
		return lines
	}
	// pad non final lines to the wrap width
	for i := 0; i < len(lines)-1; i++ {
		if StringWidth(lines[i]) < max {
			lines[i] = lines[i] + strings.Repeat(" ", max-StringWidth(lines[i]))
		}
	}
	return lines
}

func splitWords(s string) []string {
	var out []string
	cur := strings.Builder{}
	for _, r := range s {
