	for i := 0; i < n; i++ {
		for _, ls := range lines[i] {
			if len(ls) > maxRows {
				maxRows = len(ls)
			}
		}
	}
	for r := 0; r < maxRows; r++ {
		for i := 0; i < n; i++ {
			if i == 0 {
				sb.WriteString("|")
			}
			w := widths[i]
			cell := ""
			if r < len(lines[i]) {
