				if aligned != nil && r < len(aligned[i]) {
					a = aligned[i][r]
				}
				sb.WriteString(alignIn(cell, w, a))
			}
			sb.WriteString("|")
		}
		sb.WriteString("\n")
	}
}

func centerIn(s string, w int) string {
	sw := StringWidth(s)
	total := w + 2
	left := (total - sw) / 2
	right := total - sw - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
