func (e *Exporter) writeTable(t *OutTable, md bool) error {
	ncol := len(t.Cols)
	if ncol == 0 {
		return nil
	}
	widths := make([]int, ncol)
	for i := 0; i < ncol; i++ {
		hl := cellLines(t.Cols[i], e.opt.OutNoWrap)
		widths[i] = cellWidth(hl)
	}
	var headerFlat [][]string
	for i := 0; i < ncol; i++ {
		headerFlat = append(headerFlat, cellLines(t.Cols[i], e.opt.OutNoWrap))
		if w := cellWidth(headerFlat[i]); w > widths[i] {
			widths[i] = w
		}
	}
	// data
	var flat [][]string
	var align [][]bool
	maxRowLines := 0
	var rowCells [][][]string
	for _, row := range t.Rows {
		cells := make([][]string, ncol)
		for i := 0; i < ncol; i++ {
			v := ""
			if i < len(row) {
				v = row[i].ToText()
			}
			cells[i] = cellLines(v, e.opt.OutNoWrap)
			if len(cells[i]) > maxRowLines {
				maxRowLines = len(cells[i])
			}
		}
		rowCells = append(rowCells, cells)
	}
	for _, cells := range rowCells {
		ml := 0
		for i := 0; i < ncol; i++ {
			if len(cells[i]) > ml {
				ml = len(cells[i])
			}
		}
		for i := 0; i < ncol; i++ {
			ls := make([]string, ml)
			al := make([]bool, ml)
			for k := 0; k < len(cells[i]); k++ {
				ls[k] = cells[i][k]
				al[k] = isNumeric(cells[i][k])
				if w := cellWidth(cells[i]); w > widths[i] {
					widths[i] = w
				}
			}
			flat = append(flat, nil)
			_ = ls
			flat[i] = append(flat[i], ls...)
			align = append(align, nil)
			_ = al
			align[i] = append(align[i], al...)
		}
	}
	var sb strings.Builder
	sep := func(ch rune) {
		for i := 0; i < ncol; i++ {
			if i == 0 {
				if md {
					sb.WriteString("|")
				} else {
					sb.WriteString("+")
				}
			}
			sb.WriteString(strings.Repeat("-", widths[i]+2))
			if md {
				sb.WriteString("|")
			} else {
				sb.WriteString("+")
			}
		}
		sb.WriteString("\\n")
	}
	if md {
		writeFlatRows(&sb, headerFlat, widths, nil, true)
		sep('-')
	} else {
		sep('+')
		writeFlatRows(&sb, headerFlat, widths, nil, true)
		sep('+')
	}
	writeFlatRows(&sb, flat, widths, align, false)
	if !md {
		sep('+')
	}
	_, err := writeOut(sb.String())
	return err
}

// writeFlatRows writes rows from flat per-column line lists.
func writeFlatRows(sb *strings.Builder, flat [][]string, widths []int, align [][]bool, center bool) {
	n := len(flat)
	if n == 0 {
		return
	}
	maxRows := 0
	for i := 0; i < n; i++ {
		if len(flat[i]) > maxRows {
			maxRows = len(flat[i])
		}
	}
	for r := 0; r < maxRows; r++ {
		for i := 0; i < n; i++ {
			if i == 0 {
				sb.WriteString("|")
			}
			w := widths[i]
			cell := ""
			if r < len(flat[i]) {
				cell = flat[i][r]
			}
			if center {
				sb.WriteString(centerIn(cell, w))
			} else {
				a := false
				if align != nil && r < len(align[i]) {
					a = align[i][r]
				}
				sb.WriteString(alignIn(cell, w, a))
			}
			sb.WriteString("|")
		}
		sb.WriteString("\\n")
	}
}

