					sb.WriteString("|")
				} else {
					sb.WriteString("+")
				}
			}
			sb.WriteString(strings.Repeat("-", widths[i]+2))
			if md {
				sb.WriteString("|")
			} else {
				sb.WriteString("+")
			}
		}
		sb.WriteString("\\n")
	}
	if md {
		writeFlatRows(&sb, headerFlat, widths, nil, true)
		sep('-')
	} else {
		sep('+')
		writeFlatRows(&sb, headerFlat, widths, nil, true)
		sep('+')
	}
	writeFlatRows(&sb, flat, widths, align, false)
	if !md {
		sep('+')
	}
	_, err := writeOut(sb.String())
	return err
}

// writeFlatRows writes rows from flat per-column line lists.
func writeFlatRows(sb *strings.Builder, flat [][]string, widths []int, align [][]bool, center bool) {
	n := len(flat)
	if n == 0 {
		return
	}
	maxRows := 0
	for i := 0; i < n; i++ {
		if len(flat[i]) > maxRows {
			maxRows = len(flat[i])
		}
	}
	for r := 0; r < maxRows; r++ {
		for i := 0; i < n; i++ {
			if i == 0 {
				sb.WriteString("|")
			}
			w := widths[i]
			cell := ""
			if r < len(flat[i]) {
				cell = flat[i][r]
			}
			if center {
				sb.WriteString(centerIn(cell, w))
			} else {
				a := false
				if align != nil && r < len(align[i]) {
					a = align[i][r]
				}
				sb.WriteString(alignIn(cell, w, a))
			}
			sb.WriteString("|")
		}
		sb.WriteString("\\n")
	}
}

