{"command": "cd /workspace/trdsql && cat > tables.go <<'EOF'
package main

import (
	"strings"
)

// extractTables returns the file names referenced in the SQL.
func extractTables(toks []Token) []string {
	var names []string
	seen := map[string]bool{}
	expectTable := false
	inFrom := false
	i := 0
	next := func(j int) int {
		for j < len(toks) && toks[j].Type == TokSpace {
			j++
		}
		if j >= len(toks) {
			return -1
		}
		return j
	}
	for i < len(toks) {
		t := toks[i]
		if t.Type == TokSpace {
			i++
			continue
		}
		if t.Type == TokIdent {
			lt := strings.ToLower(t.Text)
			switch lt {
			case "from":
				inFrom = true
				expectTable = true
				i++
				continue
			case "join":
				expectTable = true
				i++
				continue
			case "left", "right", "full", "outer", "inner", "cross", "natural":
				i++
				continue
			case "where", "group", "order", "limit", "having", "union", "intersect", "except", "offset", "on", "using", "values", "as":
				if lt == "on" || lt == "using" {
					// skip until the end of the ON expression at depth 0
					i++
					depth := 0
					for i < len(toks) {
						tt := toks[i]
						if tt.Type == TokSpace {
							i++
							continue
						}
						if tt.Type == TokPunct {
							if tt.Text == "(" {
								depth++
							} else if tt.Text == ")" {
								if depth == 0 {
									break
								}
								depth--
							}
						}
						i++
					}
					continue
				}
				inFrom = false
				expectTable = false
				i++
				continue
			}
			if expectTable && !isReservedWord(lt) {
				if !seen[strings.ToLower(t.Text)] {
					seen[strings.ToLower(t.Text)] = true
					names = append(names, t.Text)
				}
				expectTable = false
				j := next(i + 1)
				if j >= 0 {
					nt := toks[j]
					if nt.Type == TokIdent && !isReservedWord(strings.ToLower(nt.Text)) {
						// alias
						i = j
					}
				}
				i++
				continue
			}
			i++
			continue
		}
		if t.Type == TokPunct {
			switch t.Text {
			case ",":
				if inFrom {
					expectTable = true
				}
				i++
				continue
			case ")":
				// end of subquery: possible alias
				j := next(i + 1)
				if j >= 0 && toks[j].Type == TokIdent && !isReservedWord(strings.ToLower(toks[j].Text)) {
					i = j
				}
				i++
				continue
			}
		}
		i++
	}
	return names
}

func isReservedWord(w string) bool {
	switch strings.ToLower(w) {
	case "select", "from", "where", "group", "by", "having", "order", "limit", "offset",
		"union", "intersect", "except", "join", "left", "right", "full", "inner", "outer",
		"cross", "natural", "on", "using", "as", "and", "or", "not", "in", "is", "null",
		"like", "glob", "regexp", "match", "escape", "between", "case", "when", "then",
		"else", "end", "distinct", "all", "asc", "desc", "collate", "with", "values",
		"true", "false", "current", "nulls", "first", "last", "cast", "exists", "isnull",
		"notnull", "collatenow", "set", "insert", "update", "delete", "create", "table",
		"begin", "commit", "pragma", "window", "over", "partition", "rows", "range",
		"unbounded", "preceding", "following", "exclude", "others", "ties", "nullsfirst":
		return true
	}
	return false
}
EOF
