	"os"
	"strings"
)

// debugToks renders the SQL tokens for the debug output.
func debugToks(sql string) string {
	var parts []string
	i := 0
	for i < len(sql) {
		c := sql[i]
		switch c {
		case ' ', '\t', '\n', '\r':
			j := i
			for j < len(sql) {
				c2 := sql[j]
				if c2 != ' ' && c2 != '\t' && c2 != '\n' && c2 != '\r' {
					break
				}
				j++
			}
			parts = append(parts, " ")
			i = j
		case ',', '=', ';', '(', ')':
			parts = append(parts, string(c))
			i++
		case '\'', '"', '`':
			j := i + 1
			for j < len(sql) && sql[j] != c {
				j++
			}
			if j < len(sql) {
				j++
			}
			parts = append(parts, sql[i:j])
			i = j
		default:
			j := i
			for j < len(sql) {
				c2 := sql[j]
				if c2 == ' ' || c2 == '\t' || c2 == '\n' || c2 == '\r' || c2 == ',' || c2 == '=' || c2 == ';' || c2 == '(' || c2 == ')' || c2 == '\'' || c2 == '"' || c2 == '`' {
					break
				}
				j++
			}
			parts = append(parts, sql[i:j])
			i = j
		}
	}
	var sb strings.Builder
	for _, p := range parts {
		sb.WriteString("[" + p + "]")
	}
	return sb.String()
}

// runQuery executes the query and writes the output.
func runQuery(opt *Opt, sql string) error {
	log := opt.Log
	loadConfig(opt, log)
	log.Debugf("driver: %s, dsn: %s", driverName(opt), driverDsn(opt))
	if err := connect(opt); err != nil {
		return err
	}
	toks, err := tokenize(sql)
	if err != nil {
		return wrapErr("export", err, sql)
	}
	log.Debugf("%s", debugToks(sql))
	db := NewDB()
	names := extractTables(toks)
	for _, name := range names {
		if err := importTable(opt, log, db, name); err != nil {
			return err
		}
	}
	rewritten := rewriteSQL(toks, names)
	log.Debugf("%s", rewritten)
	p := NewParser(toks)
	sel, err := p.Parse()
	if err != nil {
		return wrapErr("export", err, rewritten)
	}
	if sel.Err != nil {
		return wrapErr("export", sel.Err, rewritten)
	}
	env := &Env{DB: db, CTEs: map[string]*Table{}, Params: map[string]Value{}}
	rs, err := db.runSelect(sel, env.CTEs)
	if err != nil {
		return wrapErr("export", err, rewritten)
	}
	t := &OutTable{Cols: rs.Cols, Rows: rs.Rows}
	if opt.InNum {
		t.Cols = append([]string{"num"}, t.Cols...)
		for i := range t.Rows {
			t.Rows[i] = append([]Value{IntValue(int64(i + 1))}, t.Rows[i]...)
		}
	}
	if err := writeResult(opt, t); err != nil {
		return err
	}
	return nil
