func wrapErr(p string, err error, sql string) error {
	if sql == "" {
		return fmt.Errorf("%s: %s", p, err)
	}
	return fmt.Errorf("%s: %s [%s]", p, err, sql)
}

// rewriteSQL backquotes the table names.
func rewriteSQL(toks []Token, names []string) string {
	set := map[string]bool{}
	for _, n := range names {
		set[n] = true
	}
	var sb strings.Builder
	for _, t := range toks {
		if t.Type == TokIdent && set[t.Text] {
			sb.WriteString("`" + t.Raw + "`")
			continue
		}
		sb.WriteString(t.Raw)
	}
	return sb.String()
}

// importTable reads a file and registers it as a table.
func importTable(opt *Opt, log *Logger, db *DB, name string) error {
	file := name
	// strip ::path suffix
	if i := strings.Index(file, "::"); i >= 0 {
		file = file[:i]
	}
	var r io.Reader
	if file == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(file)
		if err != nil {
			log.Debugf("%s", err)
			return nil
		}
		defer f.Close()
		r = f
	}
	gf, base := GuessFormat(file, opt.InGuess)
	if base != "" {
		log.Debugf("Set in CSV because the extension is unknown: [%s]", base)
	}
	log.Debugf("Guess file type as %s: [%s]", gf, file)
	opt.InName = name
	im := &Importer{opt: opt, log: log}
	rows, err := im.Import(r)
	if err != nil {
		return fmt.Errorf("import: %s", err)
	}
	log.Debugf("Column Names: [%s]", strings.Join(rows.Cols, ","))
	types := make([]string, len(rows.Cols))
	for i := range types {
		types[i] = "text"
	}
	log.Debugf("Column Types: [%s]", strings.Join(types, ","))
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("CREATE TEMPORARY TABLE `%s` ( ", name))
	for i, c := range rows.Cols {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString("`" + c + "` " + types[i])
	}
	sb.WriteString(" );")
	log.Debugf("%s", sb.String())
	// insert batches
	writeInserts(log, name, rows.Cols, rows)
	t := newTable(name, rows.Cols)
	for i, rec := range rows.Rows {
		var row []Value
		for j := range rows.Cols {
			if j < len(rec) {
				var isNull bool
				if rows.Nulls != nil && i < len(rows.Nulls) && j < len(rows.Nulls[i]) {
					isNull = rows.Nulls[i][j]
				}
				if isNull || opt.InNull != "" && rec[j] == opt.InNull {
					row = append(row, NullValue())
				} else {
					row = append(row, TextValue(rec[j]))
				}
			} else {
				row = append(row, NullValue())
			}
		}
		t.Rows = append(t.Rows, row)
	}
	db.Add(t)
	return nil
}

func writeInserts(log *Logger, name string, cols []string, rows *Rows) {
	var cl strings.Builder
	cl.WriteString(fmt.Sprintf("INSERT INTO `%s` (", name))
	for i, c := range cols {
		if i > 0 {
			cl.WriteString(", ")
		}
		cl.WriteString("`" + c + "`")
	}
	cl.WriteString(") VALUES ")
	prefix := cl.String()
	batch := 500
	n := len(rows.Rows)
	for start := 0; start < n; start += batch {
		end := start + batch
		if end > n {
			end = n
		}
		var sb strings.Builder
		sb.WriteString(prefix)
		for i := start; i < end; i++ {
			if i > start {
				sb.WriteString(",")
			}
			sb.WriteString("(")
			for j := range cols {
				if j > 0 {
					sb.WriteString(",")
				}
				sb.WriteString("?")
			}
			sb.WriteString(")")
		}
		sb.WriteString(";")
		log.Debugf("%s", sb.String())
	}
}

// writeResult writes the result to the output.
func writeResult(opt *Opt, t *OutTable) error {
	ex := &Exporter{opt: opt, log: opt.Log}
	// null conversion on output
	if opt.OutNull != "" {
		for i := range t.Rows {
			for j := range t.Rows[i] {
				if t.Rows[i][j].T == VNull {
					t.Rows[i][j] = TextValue(opt.OutNull)
				}
			}
		}
	}
	out, err := newOutWriter(opt.OutFile)
	if err != nil {
		return err
	}
	if out.f != nil {
		defer out.f.Close()
		LogOut = out.f
	}
	defer func() { LogOut = os.Stderr }()
	old := outBuf.String()
	outBuf.Reset()
	if err := ex.Write(t); err != nil {
		outBuf.Reset()
		outBuf.WriteString(old)
		return err
	}
	s := outBuf.String()
	outBuf.Reset()
	outBuf.WriteString(old)
	return writeCompressed(opt, out.w, s)
}
