package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

type cfgDB struct {
	Driver string `json:"driver"`
	Dsn    string `json:"dsn"`
}

type cfgDBs struct {
	Order []string
	DBs   map[string]cfgDB
}

func (c *cfgDBs) UnmarshalJSON(b []byte) error {
	c.DBs = map[string]cfgDB{}
	var m map[string]cfgDB
	if err := json.Unmarshal(b, &m); err != nil {
		return err
	}
	c.DBs = m
	// preserve order by scanning the raw text
	c.Order = scanOrder(string(b))
	return nil
}

func scanOrder(s string) []string {
	var order []string
	i := 0
	for i < len(s) {
		if s[i] == '"' {
			j := i + 1
			for j < len(s) && s[j] != '"' {
				j++
			}
			key := s[i+1 : j]
			// find the colon
			k := j + 1
			for k < len(s) && (s[k] == ' ' || s[k] == '\t' || s[k] == '\n' || s[k] == '\r') {
				k++
			}
			if k < len(s) && s[k] == ':' {
				order = append(order, key)
			}
			i = j + 1
			continue
		}
		i++
	}
	return order
}

type config struct {
	Driver   string `json:"driver"`
	Dsn      string `json:"dsn"`
	Db       string `json:"db"`
	Database  cfgDBs `json:"database"`
}

func loadConfig(opt *Opt, log *Logger) {
	var path string
	if opt.ConfigFile != "" {
		path = opt.ConfigFile
		if _, err := os.Stat(path); err != nil {
			log.Errorf("[%s]no file", path)
			os.Exit(1)
		}
	} else {
		dir, err := os.UserConfigDir()
		if err == nil {
			path = filepath.Join(dir, "trdsql", "config.json")
		} else {
			path = filepath.Join(os.Getenv("HOME"), ".config", "trdsql", "config.json")
		}
		if _, err := os.Stat(path); err != nil {
			log.Debugf("configOpen: open %s: no such file or directory", path)
			return
		}
	}
	log.Debugf("config found: %s", path)
	b, err := os.ReadFile(path)
	if err != nil {
		log.Errorf("[%s]%s", path, err)
		os.Exit(1)
	}
	var c config
	if err := json.Unmarshal(b, &c); err != nil {
		log.Errorf("[%s]config error: %s", path, err)
		os.Exit(1)
	}
	opt.Config = c
